INSERT INTO habilidades (id, nome, traducao, descricao) VALUES
(251, 'Poison Powder', NULL, 'Spreads a cloud of poisonous powder from its wings.'),
(252, 'Surudoi Kagitsume', 'Sharp Talons', NULL),
(253, 'Poison Sting', NULL, NULL),
(254, 'Scissors Execution', NULL, 'Slices through the enemy with its left claw.'),
(255, 'Hard Shell Crab', NULL, NULL),
(256, 'Jūouken', 'Beast King Fist', 'Punches the enemy, or Chokes the life out of the opponent with its ultimate secret technique, by launching an aura in the shape of a lion''s head from its fist.'),
(257, 'Shishiou-maru', 'Lion King', 'Slices at the foe with its sentient magical sword, Shishiou-maru.'),
(258, 'Hasaigeri', 'Crushing Kick', 'Attacks the enemy with a roundhouse kick.'),
(259, 'Jūouha', 'Beast King Destruction', 'Attacks with a blast of energy from its fist.'),
(260, 'Hyakujūken', 'Hundred Beast Fist', 'Doing a series of movements with its arm, Leomon sends a barrage of lion heads against its enemy'),
(261, 'Jūga-maru', 'Beast Fang', NULL),
(262, 'Shishi Jūhazan', 'Lion Beast Wave Slash', NULL),
(263, 'Shin Jūouken', 'True Beast King Fist', 'After using Jūouken, performs a second Jūouken with its free hand.'),
(264, 'Tusk Strikes', NULL, 'Skewers the opponent with its two elongated tusks, or fires its tusks like missiles.'),
(265, 'Tundra Breath', NULL, 'Spews cold breath from its long trunk all at once, instantly freezing any opponent.'),
(266, 'Snowball', NULL, 'Fires a hard frozen snowball from its trunk.'),
(267, 'Nose Stamp', NULL, 'Hits the opponent with its trunk.'),
(268, 'Ocean Love', NULL, 'Spits out heart-shaped bubbles from its mouth that can damage enemies or cause them to lose their fighting spirit. The bubbles can also be used to protect those inside them.'),
(269, 'Nikkori Egao', 'Smiling Face', 'Charms the enemy with its smile, sometimes following up with strikes from its limbs, or heals its allies.'),
(270, 'Marine Squadron', NULL, 'Summons sea creatures to attack the enemy.'),
(271, 'Extra Smile', NULL, 'Radiates patterns of rainbow light to damage the opponent.'),
