(273, 'Smile Attack', NULL, 'Tackles with its cute tummy.'),
(274, 'Pretty Heart', NULL, 'Summons a heart to attack the enemy.'),
(275, 'Guilty Black', NULL, 'Discharges poisonous ink or dark electricity from its mouth.'),
(276, 'Neck Hanging', NULL, 'Chokes the opponent with its tentacles.'),
