(1384, 'Spinning Lariat', NULL, 'Spins around, hitting the enemy with both arms.'),
(1385, 'Ittouryoudan', 'Single-stroke Bisection', 'Fires a shock wave by crossing its two bokutō. Merges its two bokutō into a single longer, glowing blade, and attacks with it.'),
(1386, 'Kugutsu no Jutsu', 'Puppetry Technique', 'Manipulates the opponent like a puppet with a bewitching look.'),
(1387, 'Kouen', 'Crimson Blaze', 'Fires from its wings swirling flames comparable to solar prominences.'),
(1388, 'Rengokusou', 'Purgatory Claws', NULL),
(1389, 'Zanka', 'Ember', NULL),
(1390, '[N 3]', NULL, 'Shoots a barrage of fireballs upwards from its wings.'),
(1391, '[N 4]', NULL, 'Fires countless glowing needles from its body.'),
(1392, 'Rainbow Shower', NULL, 'Radiates a beam from its laser wings that burns the opponent to cinders.'),
(1393, 'Strelitzia', NULL, NULL),
(1394, 'Rodeo Gallop', NULL, 'Unleashes a powerful blow with its hind legs.'),
(1395, 'Silver Blaze', NULL, 'Fires a holy beam from its brow.'),
(1396, 'Shooting Star', NULL, 'Creates the void of space inside of both its wings, sending down shooting stars.'),
(1397, 'Pegas Drop', NULL, 'Attacks with a powerful headbutt.'),
(1398, 'Needle Rain', NULL, 'Shoots needle-like hair strands from its mane.'),
(1399, 'Necromist', NULL, 'Emits a fear-gas that steals the will of hostile Digimon, and slowly desiccates their flesh. If someone suffers this attack, there are only two options—whether to be lured completely to the world of death, or to serve Pharaohmon as an immortal, even in death.'),
(1400, 'Tut Ankh Lyl', 'The Living Image of the Night', NULL),
(1401, 'Crazy Sonic', NULL, 'Emits a high-frequency noise at the enemy, rupturing their sensory organs.'),
(1402, 'Sky Jacker', NULL, NULL),
(1403, 'Tequila Knuckle', NULL, 'Drives punches that only hit the opponent''s face with its leather-strapped fists, intoxicating them with its destructive power.'),
(1404, 'Blood Dance: Maracas Version', NULL, 'Strikes the opponent while getting into a rhythm with the maracas on its Mexican hat.'),
(1405, 'Cactus Bat', NULL, NULL),
(1406, 'Pororo Breeze', NULL, 'Flaps its wings to raise a cloud of sand, then seizes the opportunity to flee when the opponent flinches.'),
(1407, 'Sonic Ear', NULL, 'Accelerates the blades on both of its ears to the speed of sound and then slashes the enemy.'),
(1408, 'Dimension Hole', NULL, 'Summons a being from another dimension to increase an ally''s defense.'),
(1409, 'Smiley Warhead', NULL, 'Unleashes an intense headbutt without breaking its smile.'),
(1410, 'Purple Rain', NULL, NULL),
(1411, 'Beak Pierce', NULL, 'Nosedives from high in the sky and pierces the enemy with the sharp tip of its beak, penetrating even armor, regardless of its thickness, and destroying their Digicore with unparalleled accuracy.'),
(1412, 'Kaikousen', 'Mysterious Light Ray', 'Shoots a beam from the mouth.'),
(1413, 'Hell''s Bomb', NULL, 'Drops multiple bombs over a wide area.'),
(1414, 'Side Winder', NULL, 'Shoots a large barrage of missiles from its wings.'),
(1415, 'Heartner Beam', NULL, 'Releases a soft light that causes a loss of fighting spirit and soothes the hearts of its enemies.'),
(1416, 'Love and Fire', NULL, NULL),
(1417, 'Sourai', 'Blue Thunder', 'Looses intense thunderbolts from the sky, with divine fury.'),
(1418, 'Fūshikaden', 'Wind of Threads and Flower of Electricity', 'Strikes its enemy with lightning from the sky.'),
(1419, 'Raijin-no-Mai', 'Dance of Raijin', NULL),
(1420, 'Golden Triangle', NULL, 'Fires a triangular beam from its whole body that completely disassembles the enemy''s data.'),
(1421, 'Rapid Fire', NULL, 'Rapid-fires homing missiles from its arms and the revolver on its back.'),
(1422, 'Ain Soph Aur', NULL, NULL),
(1423, 'Atomic Burst', NULL, 'Cloaks itself in a barrier made of light emitted from the "Ain Soph Aur" jewels embedded in its armor, then charges into the opponent.'),
(1424, 'Split Blade', NULL, NULL),
(1425, 'Spinning Cutter', NULL, 'Rapidly spins its body using its prided speed, and tears up the opponent with the cutters on both of its arms.'),
(1426, 'Quadruple Storm', NULL, NULL),
(1427, 'Judgement Arrow', NULL, 'Fires an arrow made of the super-metal Chrome Digizoid.'),
(1428, 'Meteor Gallop', NULL, NULL),
(1429, 'Poison Pierce', NULL, 'Stings an enemy with extreme poison from its tail.'),
(1430, 'Blackout', NULL, 'Blinds the opponent''s by disseminating a slightly poisonous mist.'),
(1431, 'Prism Rainbow', NULL, 'Spews out a seven-colored beam from its trumpet-like mouth. This technique has the effect of purifying all feelings of conflict such as the enemy''s belligerence and hatred.'),
(1432, 'Dragon Drop', NULL, NULL),
(1433, 'Jamming Hertz', NULL, 'Emits radio waves that derange the opponent from the radome on its back, leaving them in a state of complete confusion.'),
(1434, 'Status Busy', NULL, NULL),
(1435, 'Spirit Boomerang', NULL, 'A cursed weapon that contains the spirits of the dead. It makes sport of the enemy with its ever-changing trajectory.'),
(1436, 'Charming Dancin''', NULL, NULL),
(1437, 'Seven Heavens', NULL, 'Fires seven super-heated spheres of light at the opponent.'),
(1438, 'Testament', NULL, 'Sacrifices its mortal life to trigger a Big Bang.'),
(1439, 'Kūchū Seven Heavens', 'Aerial Seven Heavens', 'Fires Seven Heavens in midair.'),
(1440, 'Ascension Hallow', NULL, 'Calls down powerful bolts of lightning.'),
(1441, 'Divine Breaker', NULL, 'Sends forth a formidable ball of crackling lightning from its fist.'),
(1442, 'Heaven''s Kick', NULL, NULL),
(1443, 'Seven''s Wing', NULL, NULL),
(1444, 'Final Heal', NULL, 'Fully heals itself and its allies.'),
(1445, 'Holy Sunshine', NULL, 'Submerges the battlefield in holy light.'),
(1446, 'Heat Storm', NULL, 'Attacks the opponent with a hot wind that rages in the desert.'),
(1447, 'Tusk Driver', NULL, 'Strikes the opponent with its two gigantic tusks.'),
(1448, 'Flare Buster', NULL, 'Emits a red hot blaze from both hands or sets itself on fire and rams the opponent.'),
(1449, 'Indent Screw', NULL, 'Strikes the opponent with stretched-out arms while rotating.'),
(1450, 'Psychic Wave', NULL, 'Emits a psychic wave from all its body.'),
(1451, 'Nigimitama', 'Harmonious Spirit', 'Shoots exploding clay disks at the enemy.'),
(1452, 'Aramitama', 'Violent Spirit', 'Shoots red/orange beams out of its eyes.'),
(1453, 'Sakimitama', 'Fortune Spirit', 'Summons a bird statue that emits a song.'),
(1454, 'Wool Grenade', NULL, 'Forcibly puts enemy Digimon to sleep during any battle with giant balls of wool launched from the "Wool Ball Booster".'),
(1455, 'Wool Ball Booster', NULL, NULL),
(1456, 'Silence of Lambs', NULL, NULL),
(1457, 'Kusanagi', NULL, 'Throws the big shuriken on its back at the opponent from high in the air.'),
(1458, 'Momiji Oroshi', 'Autumn Leaf Wind', 'Spins the shurikens at the tips of its extendable limbs to attack the enemy.'),
(1459, 'Nouten Saka Otoshi', 'Cranium Hill-drop', 'Holds onto the opponent as they both plunge headfirst into the ground.'),
(1460, 'Bungee Jump', NULL, 'Shurimon sticks its feet into a wall and does a bungee jump.'),
(1461, 'Konoha Kakure', 'Leaf Concealment', 'Transforms its body into a hurricane of sharp leaves, disappearing and reappearing like a ninja.'),
(1462, 'Tendril Jump', NULL, 'Flips through the air, extends its limbs, and slices at the foe with the shurikens on its feet.'),
(1463, 'Top Gun', NULL, 'Fires off energy shots while extending both of its arms ahead of itself.'),
(1464, 'Dual Sonic', NULL, 'Glides at super-speed from the sky above to crash a shock wave into the opponent.'),
(1465, 'Airfield', NULL, 'Creates a tornado and sends it against the opponent.'),
(1466, 'Nova Slash', NULL, NULL),
(1467, 'Mystic Bell', NULL, 'Generates special ultrasonic waves from the bell hanging from its neck to confound the opponent.'),
(1468, 'Milky Erode', NULL, NULL),
(1469, 'Cutter Punch', NULL, NULL),
(1470, 'Dimension Scissor', NULL, 'Cuts through all of the surrounding space with its scissors. Fires energy in the shape of its pincers.'),
(1471, 'Grand Death Screw', NULL, 'Gathers its power and drills right through the enemy with its scissors.'),
(1472, 'Zone Black Hole', NULL, 'Creates a gigantic orb of darkness and strikes the opponent with it.'),
(1473, 'Catastrophe', NULL, 'Attacks the enemy with its claws and scissors, causing a fiery explosion in the process. Fires a barrage of explosive beams from its wings.'),
(1474, 'Double Bubble', NULL, 'Spits out a lot of adhesive bubbles.'),
(1475, 'Wind Seeker', NULL, 'Manipulates the wind, generating a vacuum blade.'),
(1476, 'Silent Symphony', NULL, 'Fires destructive supersonic waves from its mouth.'),
(1477, 'Feather Slash', NULL, 'Throws the feather on its head like a boomerang.'),
(1478, 'Beak Pecker', NULL, 'Pecks at the enemy with its beak.'),
(1479, 'Loop the Hawk', NULL, 'Flips into the air and slices at the enemy with its talons.'),
(1480, 'Atomic Ray', NULL, 'Combines neutron energy and nuclear energy from the regulatory turbines on its shoulders to form a beam that annihilates enemies.'),
(1481, 'Copy Paste', NULL, 'Attacks with the batons it carries on its back.'),
(1482, 'Tempest Wing', NULL, 'Spins its body to generate a gigantic tornado.'),
(1483, 'Udjat Gaze', NULL, 'Fires a cursed beam from its eyes that hypnotizes the opponent.'),
(1484, 'Holy Dream', NULL, NULL),
(1485, 'Positron Laser', NULL, 'Fires an energy beam from the cannon on its back.'),
(1486, 'Mega Death', NULL, 'Fires dark matter from its mouth or cannon that annihilates everything within a wide radius.'),
(1487, 'Splendor Blade', NULL, 'Uses its glowing claws to attack.'),
(1488, 'Eternal Zeal', NULL, 'Spreads its wings and generates a massive, fiery explosion.'),
(1489, 'Double Positron Laser', NULL, 'Combines its Positron Laser with Imperialdramon Fighter Mode''s to deal immense damage.'),
(1490, 'Giga Death', NULL, 'Fires the Positron Laser from the face on its chest to emit a destructive energy wave. Fires a large ball of black electricity from the cannon in its chest.'),
(1491, 'Super Positron Laser', NULL, 'A charged and more powerful version of Positron Laser.'),
(1492, 'Ion Blaster', NULL, 'Releases an emitter from its chest that charges a bolt of energy that explodes.'),
(1493, 'Imperial Claw', NULL, 'Slashes with the claws on one wrist.'),
(1494, 'Imperial Crusher', NULL, 'Dashes forward, stabbing with the electrified claws of one wrist, sometimes followed by a powerful kick.'),
(1495, 'Imperial Kick', NULL, 'A midair kick.'),
(1496, 'Dragon Kick', NULL, 'Flips, bringing its heel down on the enemy.'),
(1497, 'Dragon Knee', NULL, 'Shoots forward through the air with one knee outstretched.'),
(1498, 'Hikari no Barrier', 'Light Barrier', 'Creates a shield of energy from the cannon on its arm that it can also use to encase opponents.'),
(1499, 'Chōetsu Positron Laser', 'Transcendent Positron Laser', 'Firmly plants its feet on the ground, before charging energy on its cannon and then shooting a more powerful Positron Laser.'),
(1500, 'Hell''s Grenade', NULL, 'Fires shells of a terrible, destructive energy from the muzzle inside of its mouth.')
ON CONFLICT (id) DO UPDATE SET nome = EXCLUDED.nome, traducao = EXCLUDED.traducao, descricao = EXCLUDED.descricao;

INSERT INTO habilidades (id, nome, traducao, descricao) VALUES
(1501, 'Cocoon Attack', NULL, 'Charges the opponent while in its cocoon form.'),
(1502, 'Cocoon Guard', NULL, 'Raises its defense by retracting its legs and neck into its body.'),
(1503, 'Virus Skater', NULL, 'Breathes a stream of dark, electrified gas from its mouth.'),
(1504, 'Sakura Fubuki', 'Cherry Blossom Blizzard', 'Violently sweeps the back of its head, then emits a blinding, stinging light from the faces on its hands that knocks out the opponent while they''re fascinated by the beauty of that storm of petals.'),
(1505, 'Renjishi', 'Lion Dance', 'Makes a circle with its head, sharply tapering the petals on its head where the force accumulated due to the centrifugal force, then piercing them into the opponent like shuriken.'),
(1506, 'Jumping Blow', NULL, 'An intense blow unleashed from its golden right arm.'),
(1507, 'Red Earth Gallop', NULL, NULL),
(1508, 'Shōgekiha', 'Ballistic Feathers', 'Flaps its jet black wings, driving its feathers into the opponent with a shock wave.'),
(1509, 'Satori', 'Enlightenment', 'Reads the opponent''s spirit to anticipate their attacks.'),
(1510, 'Irataka no Ken', 'Irataka Swords', 'Attacks or blocks with its swords.'),
(1511, 'Feather Sonic', NULL, NULL),
(1512, 'Crazy Giggle', NULL, 'Fires a shot of exceptionally powerful bullet of light from its mouth.'),
(1513, 'Crazy Turn', NULL, 'Attacks by extending its arms and spinning around.'),
(1514, 'Crazy Smoke', NULL, 'Blows out a poisonous smoke.'),
(1515, 'Dark Crusher', NULL, 'Hits an enemy with both hands.'),
(1516, 'Fool Out', NULL, 'Emits an unbearable discord.'),
(1517, 'Teppou', NULL, 'An intense barraging harite unleashed from its six arms.'),
(1518, 'Vajra', NULL, 'Attacks with its Vajra.'),
(1519, 'Glare Eye', NULL, 'Produces froth from its eye. Fires a ball of light from its eye.'),
(1520, 'Blood Eye', NULL, 'Confuses the enemy.'),
(1521, 'Asipatravana', NULL, 'Spins like a tornado with its body as the axis, cutting anything surrounding it with the Bǎo Fǔ on its hands.'),
(1522, 'Bǎo Fǔ', 'Treasure Axe', 'Transforms its hands into razor-sharp axes to attack.'),
(1523, 'Ammit', NULL, 'Summons a demonic beast from hell to devour the Digicores of evil Digimon, or fires waves of destructive light from its hands.'),
(1524, 'Pyramid Power', NULL, 'Imprisons its enemy in a pyramid made from beams of light, or uses pyramid power to jump up and kick the enemy.'),
(1525, 'Soul Absorption', NULL, 'Disassembles and absorbs the enemy''s data.'),
(1526, 'Erase Sickle', NULL, 'Attacks with the sickles on its arms, erasing the enemies configuration data.'),
(1527, 'Prison Fist', NULL, '3Destroys the opponent''s data at the program level. Stabs the opponent with the spines on its arm and absorbs their energy. Uses its hand to summon a vortex of dark energy.'),
(1528, 'Snatch Whip', NULL, 'Robs the opponent of their configuration data and turns it into its own.'),
(1529, 'Dot Matrix', NULL, 'Disassembles the opponent''s data into a particle state and absorbs it.'),
(1530, 'Freeze Tentacles', NULL, 'Freezes the opponent''s data with its tentacle-shaped hands, causing their vital functions to be brought to a halt.'),
(1531, 'Exile Spear', NULL, 'Twists the tentacles of one hand into a spear and stabs the opponent.'),
(1532, 'Ultimate Flare', NULL, 'Fires a huge fire blast from its mouth.'),
(1533, 'Double Impact', NULL, 'Rapid-fires its twin Berenjena shotguns.'),
(1534, 'Darkness Claw', NULL, 'Raises its sharp claws overhead and then cuts the opponent to pieces.'),
(1535, 'Heartbreak Shot', NULL, 'Locks on the enemy''s heart and takes it down with one shot.'),
(1536, 'Claw', NULL, 'Swipes with its claws.'),
(1537, 'Berenjena', NULL, 'Fires its Berenjena shotguns.'),
(1538, 'Behemoth', NULL, 'Summons Behemoth and drives into the enemy.'),
(1539, 'Pao Yù', NULL, 'Traps opponents in crystal spheres and deletes them.'),
(1540, 'Death Slinger', NULL, 'Fires a destructive wave from the Blaster on its right arm.'),
(1541, 'Beelzeb Kick', NULL, 'A powerful middle kick.'),
(1542, 'High Impact', NULL, 'Attacks with Berenjena from the air, or calls down lightning on the enemy.'),
(1543, 'Bloody Skewer', NULL, 'Pierces the enemy with beams of dark matter from its Berenjena.'),
(1544, 'Behemoth × Death Slinger', NULL, 'Rapid-fires its Blaster while riding Behemoth, before shooting a beam from it.'),
(1545, 'Exhaust Flame', NULL, 'Breathes a stream of flame from its mouth while roaring.'),
(1546, 'Plasma Blade', NULL, 'Develops plasma on its arm blades and slices the enemy, sometimes by spinning with arms outstretched.'),
(1547, 'Black Exhaust Flame', NULL, 'Breathes a stream of flame from its mouth.'),
(1548, 'Howling', NULL, 'Frightens an enemy with a fierce howl.'),
(1549, 'Dragon Slash', NULL, 'Slashes upward with the claws on both hands.'),
(1550, 'Grow Claw', NULL, 'Attacks using its huge claws.'),
(1551, 'Dark Blade', NULL, 'Attacks with the electrified claws of one hand.'),
(1552, 'Atomic Blaster', NULL, 'Fires from both gunports on its chest, destroying the enemy on the atomic level.'),
(1553, 'Hammer Edge', NULL, 'Punches the enemy with the Pendulum Blade of one arm.'),
(1554, 'Double Edge', NULL, 'Slices the enemy with the Pendulum Blades on its arms.'),
(1555, 'Giant Missile', NULL, 'Fires the giant missiles on its shoulders.'),
(1556, 'Burst Shot', NULL, 'Fires all of the heavy artillery on its body at once.'),
(1557, 'Śwabhojana', NULL, 'Generates a massive earthquake and shock wave by striking the ground with Bǎo Chuí'),
(1558, 'Bǎo Chuí', 'Treasure Mallet', 'Transforms its entire body into a gigantic hammer to smash the foe.'),
(1559, 'Howl of the Heavens', NULL, 'Unleashes a wave of force from its mouth.'),
(1560, 'Hellfire', NULL, 'An emission of scorching-hot flames from its mouth.'),
(1561, 'Inferno Gate', NULL, 'Opens the "gates of Hell" that are engraved in the earth, thrusting the opponent down into the jet-black Dark Area.'),
(1562, 'Styx Killer', NULL, 'Attacks with its claws.'),
(1563, 'Judecca Prison', NULL, 'Fires a dark corrosive wave from Gorgon. Charges forward with an electrified Balmung.'),
(1564, 'Demon''s Disaster', NULL, '3A brutal barrage of thrusts with Balmung. Repeatedly fires blasts of electricity from Balmung. Fires a beam from the tip of its lance.'),
(1565, 'Waking Dead', NULL, 'Casts a huge sphere of energy around itself using Gorgon.'),
(1566, 'Spiral Wailer', NULL, 'Attacks with its lance Balmung as lightning spirals about the blade.'),
(1567, 'Duke Charge', NULL, 'Charges its enemy with its glowing Balmung.'),
(1568, 'Falling Lance', NULL, 'Drops down from the sky, stabbing with Balmung.'),
(1569, 'Shield Destructor', NULL, 'Charges up and blasts the enemy with energy from Gorgon.'),
(1570, 'Chaos Shot', NULL, 'Gathers dark energy with Gorgon and fires it with Balmung.'),
(1571, 'Cruel Balmung', NULL, 'A strong blow using Balmung that shocks the enemy.'),
(1572, 'Culumon no Inori', 'Culumon''s Prayer', 'Heals an ally.'),
(1573, 'Keter Flare', NULL, 'Attacks with light.'),
(1574, 'Shining Evolution', NULL, NULL),
(1575, 'Culumon no Negai', 'Culumon''s Wish', NULL),
(1576, 'Grau Lärm', 'Grey Noise', 'A howl that seals the opponent''s abilities.'),
(1577, 'Schwarz Strahl', 'Black Beam', 'Fires a black beam that pierces the opponent''s Digicore.'),
(1578, 'Kimontonkou', 'Demonic Gates, Hidden Armor', 'Chants an incantation while painting a barrier in the air with its gigantic brush, confining the opponent in a labyrinth.'),
(1579, 'Jugonsatsu', 'Exorcism Scrolls', 'Wreathes its talismans around the opponent''s body, then detonates them.'),
(1580, 'Kimontonkou Genwakujin', 'Kimontonkou Glamour', 'Changes the enemy''s perception of the magical labyrinth, such as by making another Digimon invisible to them.'),
(1581, 'Final Elysion', NULL, 'Fires a beam which purifies everything from the holy shield Aegis in its left hand.'),
(1582, 'Royal Saber', NULL, 'Dispatches a strong blow from the holy lance Gram. Fires a beam or lightning bolt from Gram.'),
(1583, 'Dragon Driver', NULL, 'Takes Grani into a nosedive, driving through its foe with its lance.'),
(1584, 'Yuggoth / Yuggoth Blaster', NULL, 'Grani fires the digital bio-weapon Yuggoth.'),
(1585, 'Gram Slash', NULL, 'Lacerates the enemy with the tip of Gram. Stabs downwards from the air with Gram.'),
(1586, 'Royal Slash', NULL, 'Slashes with Gram while running towards the enemy.'),
(1587, 'Sky Gram Slash', NULL, 'The aerial version of Gram Slash.'),
(1588, 'Shield Attack', NULL, 'Charges up its Aegis and fires a beam or burst of energy from it.'),
(1589, 'Screw Saber', NULL, '3Spins with Gram outstretched, rising into the air like a tornado. Thrusts upwards into the air with an electrified Gram. Summons tornadoes that radiate outwards.'),
(1590, 'Lightning Charge', NULL, 'Fires a lightning bolt from Gram. Surrounds itself with a giant sphere of electricity.'),
(1591, 'Saber Shot', NULL, 'Gathers holy energy with Aegis and fires it with Gram.'),
(1592, 'Gram Strike', NULL, 'Stabs an enemy with Gram.'),
(1593, 'Invincible Sword', NULL, 'Uses the sacred sword "Blutgang" to cut the enemy to pieces, or slashes with it to fire a shockwave.'),
(1594, 'Quo Vadis', NULL, 'Disintegrates the enemy with energy from its spear Gungnir and consigns them to oblivion in another dimension.'),
(1595, 'Blutgang', NULL, 'A mighty stroke with the sword "Blutgang."'),
(1596, 'Gungnir', NULL, 'Stabs the enemy with Gungnir.'),
(1597, 'Dash Blutgang', NULL, 'Charges forward and stabs the enemy with "Blutgang."'),
(1598, 'Grand Cross', NULL, 'Fires ten superheated orbs in a cruciform syzygy.'),
(1599, 'Divine Feat', NULL, 'Fires a beam of holy energy.'),
(1600, 'Vedhaka', NULL, 'Disappears into a swirl of light in the sky from which it fires 108 shining Bǎo Shǐ, or breathes flames from its mouth.'),
(1601, 'Bǎo Shǐ', 'Treasure Arrow', 'Fires the Bǎo Shǐ it creates from its hairs.'),
(1602, 'Raurava', NULL, 'Imprisons its opponent in a Bǎo Yù and crushes it, completely erasing them.'),
(1603, 'Bǎo Yù', 'Treasure Ball', 'Throws an explosive crystal ball.'),
(1604, 'Trinity Burst', NULL, 'A joint attack with Taomon and Rapidmon in which they transform into streams of light that combine into one and pierce the enemy.'),
(1605, 'Assault Balancer', NULL, 'Impales the enemy with its Assault Balancer and throws them.'),
(1606, 'Megiddo Flame', NULL, 'Breathes flame that reduces everything to ash.'),
(1607, 'Hell Howling', NULL, 'Releases a powerful shock wave from howling.'),
(1608, 'Megido Bite', NULL, 'Bites its opponents with its jaws ruthlessly.'),
(1609, 'Black Sabbath', NULL, 'Uses a dark incantation to pray for a festival of death, those who hear this spell will soon die, or fires a dark shock wave from its hand.'),
(1610, 'Death Cloud', NULL, 'Generates a cloud of darkness which causes everything to decay.'),
(1611, 'Vimohana', NULL, 'Strikes the ground with its Bǎo Bàng generating a shock wave over the surrounding area.'),
(1612, 'Bǎo Bàng', 'Treasure Rod', 'Separates its tail into three nunchaku-like sections and strikes the foe with it.'),
(1613, 'Beat Knuckle', NULL, 'Assaults the opponent with earth-shattering force using its powerful claws.'),
(1614, 'Crack Bite', NULL, 'Fragments the data of the area it bites, which may cause them to collapse into malfunction.'),
(1615, 'Eden''s Javelin', NULL, 'Pierces with a javelin glowing with holy light, purifying evil hearts.'),
(1616, 'Sefirot Crystal', NULL, 'Summons ten crystals in the shape of the Sefirot and releases pink light from the crystals. Alternatively, forms several smaller crystals that directly attack the enemy.'),
(1617, 'Air Sefirot Crystal', NULL, NULL),
(1618, 'Eden''s Needle', NULL, NULL),
(1619, 'Eden''s Air', NULL, 'Creates multiple halos that emit rainbow-colored light, restoring its own energy and that of its allies.'),
(1620, 'Vahnijvala', NULL, 'Bellows out a sound wave that puts those who hear it to sleep.'),
(1621, 'Bǎo Gōng', 'Treasure Bow', 'Fires many arrows of light from a crossbow.'),
(1622, 'Strike Fang', NULL, 'Incandescently burns the metal plates on each part of it, and it is said that its whole body becomes a mass of flames and rams into the opponent.'),
(1623, 'Strike Claw', NULL, 'Incandescently burns the metal plates on its claws and cuts the opponent with them.'),
(1624, 'Kofūsatsu', 'Fox Seal Paper', 'Wreathes its talismans around the opponent''s body, then detonates them.'),
(1625, 'Bonhitsusen', 'Buddhist Brush Brandish', 'Chants an incantation while painting the Sanskrit character "Hūṃ" in the air with its gigantic brush, then hurls it at the opponent, causing it to explode.'),
(1626, 'Oṃ', NULL, 'Creates a large hemispherical shield atop a yin-yang sign that Taomon can move at will. It can also be used to electrocute an enemy caught in it.'),
(1627, 'Rajas', NULL, 'Creates a seal and throws it like a shuriken.'),
(1628, 'Ippitsu', 'One Stroke', 'Hits the enemy with a brush stroke.'),
(1629, 'Issen', 'One Flash', 'Attacks with a shining brush stroke.'),
(1630, 'Kofuusatsu', 'Fox Seal Paper', 'Wreathes its talismans around the opponent''s body, then detonates them.'),
(1631, 'Gantoretto', 'Pika Sparking', 'A striking technique using the "Tokaku Tessou" on both of its arms, it is a combo-attack technique unleashed with a great leap and rabbit-like agility.'),
(1632, 'Ninjinken', 'Ninja-speed Punch', 'A quick and stealthy Ch''uan Fa which capitalizes on its great leaping power.'),
(1633, 'Bǎo Jiàn', 'Treasure Sword', 'Crosses its twin Bǎo Jiàn and fires an X-shaped energy beam at the opponent.'),
(1634, 'Rodha', NULL, 'Uses its forefeet and upper body to strike the ground with its twin Bǎo Jiàn, generating fissures that extend up to 50 m before it. Rocks are also hurled out from the shock waves as they erupt from underground, inflicting damage on those nearby.'),
(1635, 'Súkara', NULL, 'Bores through the opponent with a red Bǎo Lún.'),
(1636, 'Bǎo Lún', 'Treasure Wheel', 'Spews a wheel of light from its mouth. Its effect differs depending on its color.'),
