(1640, 'Time Destroyer', NULL, '3Fires a spiral of energy that consigns opponents to oblivion across space and time. Creates a tear in space-time to swallow the opponents. Summons meteors and drops them on the enemies.'),
(1641, 'Chrono Paradox[N 3]', NULL, 'Opens a rift in space-time. Fires two destructive atomic rays from its mouths that freeze opponents in space-time.'),
