(1655, 'Kūchū Koyōsetsu', 'Aerial Fox Leaf Arrowheads', 'Uses Koyousetsu while in midair.'),
(1656, 'Korenkyaku', 'Fox Combo Kick', 'Spins about before unleashing several high kicks in rapid succession.'),
(1657, 'Kosengeki', 'Fox Flash Attack', 'A swift claw attack.'),
