(1666, 'Kongoukai Mandara', 'Diamond Realm Mandala', 'Strikes the ground with its "Kongou Shakujou", spreading a purifying barrier (in the form of a mandala, golden ring, spherical barrier, cherry blossoms, ball of lightning, or some combination thereof) that exorcises evil spirits.'),
