(1871, 'Nidan Jump', 'Two-Step Jump', 'Shoots up into the air after jumping.'),
(1872, 'Vergine Bomba', 'Ita: Virgin Bomb', 'Hits the enemy with its bottom. After being hit, the opponent will fall into confusion.'),
