(1874, 'Carino Anca', 'Ita: Pretty Hip', 'Hits the enemy with its bottom; immobilizing the enemy for a while.'),
(1875, 'Blast Coffin', NULL, NULL),
(1876, 'Snipe Steal', NULL, 'Steals items from the opponent.'),
(1877, 'Fire Cloud', NULL, 'Changes its surroundings into a firestorm.'),
