(1882, 'Flame Toss', NULL, 'Tosses a small fireball.'),
(1883, 'Marut Cyclone', NULL, 'Blows the enemy away with powerful winds, or spins to slice the enemy repeatedly with its Critical Arms.'),
(1884, 'Critical Arm', NULL, 'Slashes the enemy with the blowtorch-like blades of its arms.'),
(1885, 'Phantom Pain', NULL, 'Curses the opponent with a breath of darkness that rots their body and data. Can also take the form of dark power released from a magic circle.'),
