(1889, 'Empress Emblaze', NULL, 'Uses a magic circle to summon an eldritch, hand-shaped monstrosity which attacks the opponent.'),
(1890, 'Wheel Grinder', NULL, 'Spins and then throws spiked wheels, or extrudes spinning spikes from one of its front wheels and fires them at the end of a cable.'),
(1891, 'Steam Bomb', NULL, 'Uses bombs of the steam blowing from its smokestack.'),
(1892, 'Spiral Masquerade', NULL, 'Chops up the opponent with the four sash-blades that extend from its armor.'),
(1893, 'Urgent Fear', NULL, 'Instantly comes into point-blank range, shooting the opponent in the chest with shock waves from the Pile Bunker on its right arm.'),
