(1897, 'Dunkel Schneiden', 'Dark Slice', 'A rapid triple thrust with its spear.'),
(1898, 'Luft Endlich Meteor', 'Aerial Final Meteor', 'Uses Endlich Meteor in midair.'),
(1899, 'Dunkel Messer', 'Dark Knife', 'A flying kick.'),
(1900, 'Dunkel Rakete', 'Dark Rocket', 'Kicks off the ground with its spear while dashing to kick the opponent.'),
(1901, 'Dunkel Sarg', 'Dark Coffin', 'Transforms into a dark aura that wraps around the enemy.'),
(1902, 'Intensiv Endlich Meteor', 'Intensive Final Meteor', 'A more powerful, charged-up version of Endlich Meteor.'),
(1903, 'Luft Intensiv Endlich Meteor', 'Aerial Intensive Final Meteor', 'An aerial version of Intensiv Endlich Meteor.'),
(1904, 'Terrible Dance', NULL, 'A graceful roundhouse kick.'),
(1905, 'Deadly Roll', NULL, 'A magical roundhouse kick.'),
(1906, 'Divine Atonement', NULL, 'The Seven Great Demon Lords'' crests appear on its wings, then fires seven super-powered beams at the opponent.'),
(1907, 'Purgatorial Flame', NULL, 'Projects a huge flame of darkness from its mouth and sometimes from the Gehenna sphere.'),
(1908, 'Dimension Slasher', NULL, 'Attacks with sharp claws that can pierce dimensional walls.'),
(1909, 'Satan no Ikari', 'Satan''s Wrath', 'Uses the orb, Gehenna, to emit a ray of destruction.'),
(1910, 'Machine Gun Destroy', NULL, '3Simultaneously fires all its artillery weapons at all locked targets, then pulverizes its main target at high speed. Empties each of its artillery weapons in turn, discards them, then fires twin beams from its chest armor before entering its Detached state. While airborne, fires a barrage from its Strike Phantom at the target.'),
(1911, 'Starlight Velocity', NULL, 'In its Detached state, charges through the enemy at superluminal speeds. Anything that touches the bands of light in its wake is erased.'),
(1912, 'Magna Blade', NULL, 'In its Detached state, slashes repeatedly with the light sword hidden in its arm.'),
(1913, 'Magna Cannon', NULL, 'Fires energy bullets from its Sniper Phantom.'),
(1914, 'Aero Magna Blade', NULL, 'In its Detached state, performs Magna Blade in mid-air.'),
(1915, 'Corona Sanctions', NULL, 'Attacks with a magnificent aerial assault while clad in flames.'),
(1916, 'Mugenhadō', 'Endless Surge', 'A shock wave fired from its hands. A combo of punches followed by a pillar of fire.'),
(1917, 'Generous Mirror', NULL, 'It reflects an attack with its Irony no Tate, or uses the Irony no Tate to fire a blast of light.'),
(1918, 'Offset Reflector', NULL, 'It catches an attack in one mirror and fires it back from the other mirror with its characteristics reversed.'),
(1919, 'Transceirave', NULL, 'Pulverizes the opponent.'),
(1920, 'Laser Translation', NULL, 'Scans the enemy in order to copy their appearance and powers, which it further enhances.'),
(1921, 'Nikukyū Punch', 'Paw Punch', 'A combination of punches.'),
(1922, 'Neko Claw', 'Cat Claw', 'Scratches the enemy with its foreclaws or with a flying kick.'),
(1923, 'Core Dart', NULL, 'Surrounds its crystal ball with fire and throws it at its enemies.'),
(1924, 'Blast Fire', NULL, 'Envelops its sword with a single flame and then delivers a slash attack with increased power.'),
(1925, 'Gehenna Flame', NULL, 'Spits hellfire from its mouth to inflict death and eternal suffering. Conjures a gigantic sphere of flame many times its own size.'),
(1926, 'Necro Interrogation', NULL, 'Throw a deadly sphere to inflict great damage.'),
(1927, 'Tanuki Neiri', 'Play Possum', 'Dodges the situation by fake sleeping when it gets in a pinch.'),
(1928, 'Nigeashi Dash', 'Escape Dash', 'Escapes with a dash.'),
(1929, 'Are?', 'Huh?', 'Swells up with gas and explodes, spreading poison gas and reappearing elsewhere.'),
(1930, 'Yattā', 'Yippee!', 'It slips on a banana peel, tossing the peel at an enemy.'),
(1931, '1, 2, 3, 4, 5, 6, 7!', NULL, 'Belches a green bubble of gas that floats toward the enemy.'),
(1932, 'Gas da', 'Gas!', 'Fills its pants with farts and then flies around like a popped balloon shooting gas everywhere.'),
(1933, 'Arere?', 'Huh?', 'Unleashes a deadly fart.'),
(1934, 'Deep Sorrow', NULL, 'Creates a storm of despair with its wings.'),
(1935, 'Stun Claw', NULL, 'Releases an electric blast from its hands.'),
(1936, 'Cosmic Ray', NULL, 'Fires a dazzling laser beam from its mouth.'),
(1937, 'Tempest', NULL, 'Flaps its wings, creating a tempest.'),
(1938, 'Heaven''s Ripper', NULL, 'Charges at the opponent with staggering momentum, cutting them to pieces with the blades covering its body.'),
(1939, 'Holy Espada', 'Holy Sword', 'Slashes the opponent with a cross-shaped energy blast.'),
(1940, 'Ruin Laser', NULL, 'Launches an attack from the back of its arms.'),
(1941, 'Tooth-spear', NULL, 'Slashes using the tip of its tail.'),
(1942, 'Licht Nagel', 'Light Nail', 'Slices up its enemies with claws on both arms that radiate with light.'),
(1943, 'Licht Bein', 'Light Leg', 'Hits its enemies swiftly like a ray of light.'),
(1944, 'Accel Arm', NULL, 'Grips and crushes the enemy with its power-type arm.'),
(1945, 'Yakusa-no-Ikazuchi', 'Eight Thunder Gods', 'Points ZERO-ARMS: Orochi''s sword of light at the heavens, which rain incessant lightning bolts. Summons a spiraling thundercloud from which eight dragons of lightning emerge to attack the enemy.'),
(1946, 'Ama-no-Habakiri', 'Heavenly Wings Beheading', 'Slashes through everything in the world with the blade of light extending from ZERO-ARMS: Orochi.'),
(1947, 'ZERO-ARMS: Orochi', NULL, 'Fires from ZERO-ARMS: Orochi two spheres of energy, red and blue, that merge and cause a big explosion.'),
(1948, 'Thunderstorm', NULL, 'Flaps wings clad in electricity, generating a storm of lightning.'),
(1949, 'Spark Wing', NULL, 'Fires out countless electrically-charged feathers like rain.'),
(1950, 'Shokubutsusei no Awa', 'Vegetable Bubbles', 'Blows bubbles from its mouth to make the opponent slippery and files away, leaving only its scent behind while hindering their movements.'),
(1951, 'Cool Running', NULL, NULL),
(1952, 'Kyū Break Spark', 'Emergency Break Spark', NULL),
(1953, 'Kyū Brake Spark', 'Emergency Brake Spark', 'Suddenly brakes right in front of the enemy, sending hot sparks flying.'),
(1954, 'Shining V Force', NULL, 'Fires a ray of energy from the massive V on its chest.'),
(1955, 'Ulforce Saber', NULL, 'Generates a beam-sword weapon from the V Bracelet on its right wrist.'),
(1956, 'Dragon Impulse X', NULL, 'Surrounds itself in an aura of energy shaped like a dragon, then rams against its target, unleashing both Ulforce Sabers, then slashes its target in an X-shaped pattern.'),
(1957, 'Tense-great Shield', NULL, 'Generates an energy shield from the V Bracelet on its left wrist. This shield is powered up by the "Ulforce", allowing it to rewrite its data faster than direct deletion attacks can keep up with.'),
(1958, 'Mud Pump', NULL, '3Dispatches soldiers from within. Blasts water from its arms. Fires a stream of projectiles like miniature Valvemon.'),
(1959, 'Octagon Attack', NULL, 'Attacks the enemy with its arms.'),
(1960, 'Valve Extreme', NULL, 'Fires a powerful beam of condensed energy.'),
(1961, 'Force Rain', NULL, 'Fires a barrage of arcing beams.'),
(1962, 'Zone Deleter', NULL, 'Flaps its wings to blow the opponent and all the space around them into another dimension. Draws a circle around the opponent with the tip of its wing, creating a sphere of darkness that deletes everything caught within it.'),
(1963, 'Master of Darkness', NULL, 'Converts the opponent''s nature to darkness, allowing it to manipulate them. Fires a beam from its central eye.'),
(1964, 'Corona Blaster', NULL, 'Fires lasers that rival a solar heat ray from the Rudriya Darpaṇa. Jumps into the air, cloaked in flames, performing a double uppercut.'),
(1965, 'Flame Storm', NULL, 'Sets its whole body aflame, then releases a high-temperature tornado by flapping its wings. Fires a barrage of bolts of flame from the Rudriya Darpaṇa.'),
(1966, 'Crimson Fanger', NULL, 'Charges the enemy down with the Rudriya Darpaṇa.'),
(1967, 'Atomic Corona Blaster', NULL, 'Fires a prolonged barrage of lasers from the Rudriya Darpaṇa.'),
(1968, 'Salamander Glide', NULL, 'Glides through the air, hitting anything in its path.'),
(1969, 'Drag Fanger', NULL, 'Assaults the enemy as a dragon of flames.'),
(1970, 'Fire Below', NULL, 'While airborne, fires the Rudriya Darpaṇa downwards at an angle.'),
(1971, 'Wildfire', NULL, 'Unleashes a massive tornado of flame around itself.'),
(1972, 'Pandora Dialogue', NULL, 'Repeatedly preserves the opponent''s attacks within space and time, then plays them back at high speed.'),
(1973, 'Eternal Nirvana', NULL, 'Imprisons the opponent within the Space-time Stones for an eternity.'),
(1974, 'Licht Sieger', 'Deu: "Light Victor"', 'Slashes with the Licht Schwert swords.'),
(1975, 'Licht Sieger α', 'Deu: "Light Victor α"', 'Attacks with its Licht Schwert.'),
(1976, 'Licht Sieger β', 'Deu: "Light Victor β"', 'Attacks with its Licht Schwert.'),
(1977, 'Licht Sieger γ', 'Deu: "Light Victor γ"', 'Attacks with its Licht Schwert.'),
(1978, 'Zwei Sieger', 'Deu: "Two Victors"', 'Unleashes light-ball from a Licht Schwert cross-slash.'),
(1979, 'Strahl', 'Deu: "Beam"', 'Release optical lasers from both eyes.'),
(1980, 'Licht Kugel', 'Deu: "Light Bullet"', 'Fires laser shots from arm cannon.'),
(1981, 'Drohung Strahl', 'Deu: "Threat Ray"', 'Wolfmon grabs his opponent, and quickly connects his Light Swords together, performing a double bladed uppercut-slash.'),
(1982, 'Licht Kleiden', 'Deu: "Light Suit"', 'Wolfmon dashes forward and is consumed by a mass of light energy, which takes the shape of a biting wolf''s head.'),
(1983, 'Himmelfahrt', 'Deu: "Ascension"', 'Wolfmon connects his Light Swords and leaps into the air while quickly spinning, rising fast and creating a whirwind around him.'),
(1984, 'Luft Erschlagen', 'Deu: "Aerial Slaying"', 'Unleashes a quick blow using its Licht Schwert while in mid-air.'),
(1985, 'Luft Licht Kugel', 'Deu: "Aerial Light Bullet"', 'Fires Licht Kugel from the air.'),
(1986, 'Luft Intensiv Licht Kugel', 'Deu: "Aerial Intensive Light Bullet"', 'Fires Intensiv Licht Kugel from the air.'),
(1987, 'Intensiv Licht Kugel', 'Deu: "Intensive Light Bullet"', 'Licht Kugel charged up.'),
(1988, 'Rolling Black', NULL, NULL),
(1989, 'Paint Splash', NULL, 'Spits out ink from its mouth.'),
(1990, 'Electric Bind', NULL, 'Binds the opponent with its elongated tentacles and unleashes an intense electric shock.'),
(1991, 'Digicabolic Steroid', NULL, 'Shoots a jet of slime from the mouth on its abdomen.'),
(1992, 'Leaf Cyclone', NULL, 'Rotates the leaves around its head and fires them.'),
(1993, 'Thousand Spike', NULL, 'Makes innumerable roots lurking in the ground pop up onto the surface all at once, skewering enemies in the area.'),
(1994, 'Demon''s Shout', NULL, 'Drives the enemy insane with a curse-filled shout. Controls the action of other Digimon.'),
(1995, 'Volcanic Driver', NULL, 'Uses the eruptive power of the volcanoes on its shoulders to slam the enemy into the ground head-first.'),
(1996, 'Diamond Fist', NULL, 'The strongest fist that can pierce even Chrondigizoit.'),
(1997, 'Angel Dust', 'N/A', 'Sprinkles a mysterious powder over its opponent that puts them in a happy mood.'),
(1998, 'Ragnarök Cannon', NULL, 'Blasts a massive energy beam from its chest cannon at its foe.'),
(1999, 'Gimlet Gun', NULL, 'Pierces the opponent with its tail.'),
