(2020, 'Wind of Pain', NULL, 'Flies up into the air and hurls the feathers of its hair and wings as pointed arrows.'),
(2021, 'Gilgamesh Upper', NULL, 'Hits the foe with a powerful hook.'),
(2022, 'Speed Star', NULL, 'Charges at ultra-high speed and cuts its opponent to pieces with its Wing Blades.'),
(2023, 'Solar Laser', NULL, 'Absorbs light energy through its mouth then, at the critical point, spews a laser beam.'),
(2024, 'Klinge Windrad', 'Deu: Blade Windmill', 'Spins into the air, slashing the opponent with all the blades on its body.'),
(2025, 'Militant Angriff', 'Deu: Militant Attack', 'Glides and uses its Wing Blades and tail to attack.'),
(2026, 'Licht Torpedo', 'Deu: Light Torpedo', 'Charges the opponent while enveloped in light.'),
(2027, 'Klinge Wirbelwind', 'Deu: Blade Whirlwind', 'Spins its body and attacks with its Wing Blades from the air.'),
(2028, 'Earthquake', NULL, 'Strikes and raises up the ground with intense force after a huge jump.'),
(2029, 'Hurricane Bomber', NULL, 'Stretches out its arms and then unleashes a double lariat by rapidly spinning.'),
(2030, 'Wheel Rush', NULL, 'Performs a spinning slash with the rapiers in its hands.'),
(2031, 'Sword Dancer', NULL, 'Minces the enemy with its long arms as if it were dancing.'),
(2032, 'Destroyed Crash', NULL, 'Crashes into the opponent with its spiked wheel, or turns the wheel into a spiked ball and fires it at the enemy in segments.'),
(2033, 'Limited Express Attack', NULL, 'Charges over the enemy at red-hot speed.'),
(2034, 'Snake Eye Break', NULL, 'Summons one or more of its flexible Grotte Hammers from the ground or its armor and hits the enemy with them. The attack can be used to petrify and smash enemies.'),
(2035, 'Jack in the Box', NULL, 'Jumps out of the ground and attacks with its Grotte Hammer.'),
(2036, 'Atemigaeshi', 'Bodystrike Reversal', 'Knocks the enemy down by countering their attack, then strikes at their vitals.'),
(2037, 'Crescent Dawn', NULL, 'Slashes the enemy with a sweep of its Kuma Tsume.'),
(2038, 'Sonic Voice', NULL, NULL),
(2039, 'Captain Cannon', NULL, 'Fires a gigantic cannonball from its musket.'),
(2040, 'Liquid Bullet', NULL, NULL),
(2041, 'Taikyoku', 'Taiji', 'Disassembles things into the extremes of light and darkness and fires them as a blast from its mouth.'),
(2042, 'Oukai', 'Yellow Circle', 'Generates a huge typhoon of earth.'),
(2043, 'Koutei-no-Kiba', 'Fang of the Emperor', 'Bites the enemy.'),
(2044, 'Jet Binter', NULL, 'Fires from both arms with the power of the wind.'),
(2045, 'Ultra Turbulence', NULL, 'Generates an unprecedented turbulence from its gigantic pinwheel and blows the opponent away.'),
(2046, 'Spike Buster', NULL, 'Swings the spear it holds in its right hand at the speed of light, generating a shock wave.'),
(2047, 'Shot Claw', NULL, 'A combination of attacks with its spear.'),
(2048, 'Kuzuryūjin', 'Nine-headed Dragon Formation', 'Releases the eight dragon''s veins dwelling within Gaia, then becomes the final dragon itself and pulverizes the opponent with its greatsword. Plunges the Ryūgonken into the ground, from which it unleashes nine spectral dragons made of fire which seek the opponent.'),
(2049, 'Enryūgeki', 'Flame Dragon Strike', 'Fires arrows from the Ryūgonken, the flames of which are so intense that they become a white light.'),
(2050, 'Hikuzuryuujin', 'Soaring Nine-headed Dragon Force', 'Roars into the sky engulfed in flames, following up with a sword slash.'),
(2051, 'Enjin', 'Flaming Edge', 'Slashes the enemy with the Ryūgonken.'),
(2052, 'Kuuenjin', 'Soaring Flaming Edge', 'The aerial version of the normal Enjin.'),
(2053, 'Hayatehomura', 'Storming Flame', 'A rushing skewer with the Ryūgonken.'),
(2054, 'Rengokukenbu', 'Purgatory Sword Dance', 'A vicious series of sword combos.'),
(2055, 'Ryūgonken', 'Dragon''s Soul Sword', 'A sweeping horizontal slash with the Ryūgonken.'),
(2056, 'Schwarz Donner', 'Deu: Black Thunder', 'Fires a black spirit shot from its mouth.'),
(2057, 'Schwarz König', 'Deu: Black King', 'Pulverizes the opponent with its whole body clad in a black lion-shaped aura.'),
(2058, 'Luft Schwarz König', 'Deu: Aerial Black King', 'Uses Schwarz König in midair.'),
(2059, 'Schwarz Gewehr', 'Deu: Black Rifle', 'A downward slash with the claws on its forelegs.'),
(2060, 'Pushū', NULL, 'Spits out a paint-mixed water gun.'),
(2061, 'Crazy Crane', NULL, 'Swings the crane on its back at the enemy.'),
(2062, 'Hyper Bulldozer', NULL, NULL),
(2063, 'Baby Sling', NULL, 'Fires a metal ball or other projectile from its slingshot with perfect accuracy.'),
(2064, 'Mischievous Hoop', NULL, 'Trips the enemy with a throwing wheel that entangles their leg.'),
(2065, 'Fire Men', 'Fire Mask', 'Wreathes its Shinai in flames and aims for the opponent''s head.'),
(2066, 'Thunder Kote', 'Thunder Gauntlet', 'Strikes at the enemy''s arms with an electrified attack.'),
(2067, 'Ryūsei-giri', 'Meteor Slash', 'An overhead slash that hits multiple places simultaneously.'),
(2068, 'Inazuma-giri', 'Lightning Slash', 'An electrified slash.'),
(2069, 'Kouga-ryū Kage Bunshin', 'Kouga Style Shadow Clone', 'Forms clones of itself, which attack the enemy simultaneously.'),
(2070, 'Makibishi', 'Caltrop', NULL),
(2071, 'Blade Twister', NULL, 'Creates a tornado around the enemy, and minces them with a vacuum blade.'),
(2072, 'Sanrensei', 'Trinary Star', 'Shoots diamond-shaped seals from its brow.'),
(2073, 'Ryoute no Kama', 'Two-Handed Sickle', 'Attacks with the sickles on its arms.'),
(2074, 'Dino Flash', NULL, 'Fires an extremely high-temperature wind that is released from its mouth instantaneously, like a flash.'),
(2075, 'Digitalize of Soul', NULL, '3Spreads the wings on its back and flies up high, then deploys a magic circle even larger than the sky, with which it summons a legendary monster from another dimension. Fires green energy beams from its hands. Fires green energy beams from its hands. If it defeats an enemy with them, it summons a legendary monster from another dimension to take the enemies'' place who then joins Alphamon as an ally in battle.'),
(2076, 'Seiken Gradalpha', 'Holy Sword Gradalpha', 'Draws out a convergence of light that was pierced into the center of a magic array and stabs it through the opponent.'),
(2077, 'Alpha inForce', NULL, NULL),
(2078, 'Kyūkyoku Senjin Ouryūken', 'Ultimate-Battle-Blade-OURYUKEN', 'Attacks with the Ouryuken.'),
(2079, 'Ouryūken', 'OURYUKEN', 'Attacks with the Ouryuken.'),
(2080, 'Ghost Surprise', NULL, 'Camouflagues itself while in the sea to deceive the opponent.'),
(2081, 'God Matrix', NULL, 'Fires a beam of light from its eyes. Everything hit by this attack is reduced to nothing but 0''s and 1''s of primitive data.'),
(2082, 'Dystopia Lances', NULL, 'The huge number of tentacles growing as its limbs all charge to pierce its target.'),
(2083, 'Pandemonium Lost', NULL, 'Unleashes all of the Dark Area''s evil energies at once as an ultra-high-temperature explosion that burns up everything without a trace.'),
(2084, 'Death Lure', NULL, 'Uses its demonic staff "Death Lure" to tempt Digimon into an inescapable living hell, converting them to wickedness. Summons ghosts from its wand that attack the enemy.'),
(2085, 'Greedy Wand', NULL, 'Attacks with Barbamon''s favorite wand, Death Lure.'),
(2086, 'Jigoku no Kaen', 'Hell''s Flame', 'Shoots a stream of fire from Death Lure.'),
(2087, 'Dengeki Biririn 185V', 'Electric Shock 185V', 'Generates electricity to attack the enemy.'),
(2088, 'Nitro Stinger', NULL, 'Fires from its super-large caliber laser cannon which can shoot through even heavy armor.'),
(2089, 'Sky Rocket ∞', 'Sky Rocket Infinity', 'Shoots missiles from its honeycomb-shaped missile container.'),
(2090, 'Metal Cast', NULL, 'Either pierces the enemy with its steel arms to tear out their Digicore, or makes a combo attack consisting of a stomp, tail whip, and bite, or extends wires from its tail to electrocute enemies.'),
(2091, 'Cannonball', NULL, 'Fires cannonballs from its mouth.'),
(2092, 'Metal Impulse', NULL, 'Blasts everything away except the enemy''s Digicore. Skewers the oppponent with its claws, destroying their data.'),
(2093, 'DORU Din', NULL, 'A silent attack that erases everything around it. Shoots a fiery blast from its hands.'),
(2094, 'Metal Meteor', NULL, 'Fires a huge, explosive iron ball of super-high mass from its mouth.'),
(2095, 'Bloody Cave', NULL, 'It tears through the enemy''s armor with the horn on its head and engulfs its Digicore.'),
(2096, 'Process F', NULL, 'Connects its arms to the ground to create a big area of energy around itself, then releases them to erect multiple pillars of energy that impales its opponents, killing them instantly. Detects the opponent''s Digicore and rips it out with its claws.'),
(2097, 'Process 0', NULL, 'Disassembles and deletes the opponent, appearing to smash them with its hand.'),
(2098, 'Dark Spreader', NULL, 'Uses the "Dark Virus" to damage the enemy with a blast from the gem in its midsection.'),
(2099, 'Ogre Flame', NULL, 'Fires super-high temperature shells in a semi-liquid state similar to magma from its mouth.'),
(2100, 'Splatter Hunting', NULL, 'Grasps the opponent with its claws and then brings them down.'),
(2101, 'Ground Fang', NULL, 'Pins the enemy down and stabs and tears them with its fangs.'),
(2102, 'Highland Fang', NULL, 'Swings its fangs downward from an elevation to cut through the enemy, or attacks multiple times with the claws on its forelegs.'),
