(2186, 'Rosen Blood', NULL, '"Aphroditear" , the drops on its petals that are seen when incurring the wrath of Rosemon, are said to be the tears of Rosemon''s love, and Digimon that lay their eyes on them are eventually annihilated by its Special Move "Rosen Blood", in which they personally embrace Rosemon''s thorned whips despite knowing that they will get injured,'),
