(2866, 'Dadada Minchi', 'Strike, Strike, Strike, Mince', 'Showers the opponent in a high-speed barrage using the Roketto Dīng​pá, crushing them appallingly flat.'),
(2867, 'Buta no Maruyaki', 'Roast of the Pig', 'Embraces the opponent with its body, which has burst into flames from the fury of its hunger, roasting them well-done.'),
(2868, 'God of Death Snatcher', NULL, 'Extends its right arm, deleting anything it touches.'),
(2869, 'Balefire-Eyes', NULL, 'Releases its fathomless power from the red eyes in its chest, transforming all of its surroundings into nothingness.'),
(2870, 'Eternal Darkmare', NULL, 'Instantly destroys the opponent''s data by flapping its jet-black wings.'),
(2871, '??', NULL, NULL),
