(2873, 'Burning Boogie', NULL, 'Fires streams of fire and boiling red liquid from its armor.'),
(2874, 'Tuwarmon Missile Storm', NULL, 'Fires the spikes from its shoulders as missiles.'),
(2875, 'Tyrant Collbrande', NULL, 'Transforms its anger into a flaming sword and attacks with it.'),
(2876, 'Burning the Dragon', NULL, 'Stabs a dragon''s vein within the land to modify the terrain and attack enemies.'),
(2877, 'Dragon Breastonic Fire', NULL, 'Fires streams of flame from symbols on its chest.'),
(2878, 'Dragon Breath Tonic Fire', NULL, 'Fires streams of flame from the symbols on its chest.'),
(2879, 'Ekaki Kaki', 'Artist Sketch', 'Licks a picture, making its subject a reality.'),
(2880, 'Colorful Change', NULL, 'Changes the color of its attacks, also changing their element in the process.'),
(2881, 'Mini Mini Ekakimon', NULL, 'Summons small copies of itself to attack the enemy.'),
(2882, 'Lightning Shoot', NULL, 'Places a ball of light on the ground and shoots it at the enemy.'),
(2883, 'Lightning Overhead', NULL, 'Lifts the ball high up in the air and shoots it.'),
(2884, 'Greatest Sonic Wave', NULL, 'Beats its stomach drum and emits a shockwave from its mouth.'),
(2885, 'Gold Bowling', NULL, 'Attacks by throwing its collected pool of money.'),
(2886, 'Gold Press', NULL, 'Uses its entire body to press down on the opponent.'),
(2887, 'Comet Launcher', NULL, NULL),
(2888, 'Mega God of Death Snatcher', NULL, 'A more powerful version of DarknessBagramon''s God of Death Snatcher.'),
(2889, 'Chouriki Meidouha', 'Super Powered Rumbling Breaker', 'Fires cataclysmic blasts of energy from its guns.'),
(2890, 'Final Strike Roll', NULL, 'Performs a forward rolling slash with Olympia Kai drawn and filled with power.'),
(2891, 'Night Stalker', NULL, 'Extends the Medullia, which pursues the opponent anywhere to swallow them whole.'),
(2892, 'Love Poison', NULL, 'Uses its glamour to exploit the vitality of the opponents that inhale the toxic mist sprayed from the Medullia''s mouth.'),
(2893, 'Hebi Punch', NULL, 'Strikes the opponent with the Medullia.'),
(2894, 'Olympia Kai', NULL, NULL),
(2895, 'Madness Merry-go-round DX', NULL, 'Performs a spinning slash, too quick to catch with the eyes, with the Olympia Kai and Medullia, creating a tornado that instantly tears the opponents it touches limb from limb.'),
(2896, 'Gouradarai Gun', 'Strength of Silk and Strike of Thunder Gun', NULL),
(2897, 'Majūryoku Jubakujin', 'Demonic Gravity Curse Formation', NULL),
(2898, 'Nightmare Raid', NULL, 'Fires the Evilvil at multiple enemies.'),
(2899, 'Bloody Stream Glade', NULL, 'Freely extends both of its arms, reliably captures its opponent, and wrenches them apart after forcing them to divulge all their information.'),
(2900, 'Gardiac Raid', NULL, NULL),
(2901, 'Giga Cardiac Raid', NULL, NULL),
(2902, 'Flame Hellscythe', NULL, 'Slashes the enemy with the Flame Hellscythe covered in infernal flames.'),
(2903, 'Demon''s Crystal', NULL, 'A summoning technique which keeps tormenting the enemy until they die.'),
(2904, 'Viking Vuffet', NULL, 'Swings its axes down vertically over and over, chopping the opponent to bits.'),
(2905, 'Age of Discovery', NULL, 'Jörmungandr, from its left shoulder, takes the opponent away to Jötunheimr.'),
(2906, 'Dream Comes True', NULL, 'Surtr, from its right shoulder, asks for the opponent''s wishes and pretends to grant them without actually doing so.'),
(2907, 'Dual Tomahawk Boomerang', NULL, 'Hurls its Dual Tomahawk axes effortlessly.'),
(2908, 'Hell & Thunder', NULL, 'Attacks with its sword of lightning and Barbamon-based sword of darkness.'),
(2909, 'Heaven & Break', NULL, 'Attacks with its holy lance and the spikes on its grappling hand.'),
(2910, 'Ice & Fire', NULL, 'Attacks with its swords of ice and fire.'),
(2911, 'Sword of Meteor', NULL, 'Slashes repeatedly with its swords.'),
(2912, 'Data to Data', NULL, 'Heals itself and increases its strength.'),
(2913, 'Omega Death Blade', NULL, 'A furious barrage of sword attacks that electrocutes the enemy and may cause their immediate death.'),
(2914, 'Mugen Sword Rain', 'Infinite Sword Rain', 'Rains swords on all its enemies.'),
(2915, 'Heavy Metal Vulcan', NULL, 'Fires streams of flaming bullets from its chest.'),
(2916, 'Victorize Banking', NULL, 'Unleashes flaming V shapes from the V-shaped crest on its head.'),
(2917, 'Hard Rock Damashī', 'Hard Rock Spirit', 'Channels its burning passion into fire blasts from its palms, which can be flung over a distance or used to strike at close range.'),
(2918, 'Beat Slash', NULL, 'Turns its feet into blades and drills into the opponent with them. Turns its feet into blades and kicks at the opponent, creating a cutting shockwave.'),
(2919, 'Omega the Fusion', NULL, 'Channels the Omega inForce into an aura resembling Omegamon, then tackles or shoots it at the opponent.'),
(2920, 'Sound Finish', NULL, 'Emits ultrasonic waves to immobilize the enemy.'),
(2921, 'Giga Scream', NULL, 'Sings at full volume and sends out a shock wave.'),
(2922, 'Bead-drown', NULL, 'Instantly gathers trace elements and converts them to liquid around the opponent''s head.'),
(2923, 'Poisonous Force', NULL, 'Paralyze the enemy force''s chain of command'),
(2924, 'Tiger Typhoon', NULL, 'Consumes everything.'),
(2925, 'Dengeki Haguhagu Sneaker', 'Shocking Hug-hug Sneaker', 'Repeatedly strikes the opponent with the sneakers on both of its arms.'),
(2926, 'Tongari Head', 'Pointy Head', 'Loses control of itself and charges the opponent.'),
(2927, 'Anja Serenade', NULL, 'Revives itself over and over with the "Anja Serenade" in its heart.'),
(2928, 'Speed Nightmare', NULL, 'Stabs with the hallucinogens from it''s poisonous spear.'),
(2929, 'Nightmare Pandemic', NULL, 'Uses the poisonous nails from its gloved hands to paralyze the foe. The more fingers used, the worse the effect.'),
(2930, 'Fairy Powder', NULL, 'Using its fairy dust, it temporarily turns the opponent into a baby Digimon.'),
(2931, 'Petermon Syndrome', NULL, 'A combo attack with Petermon that forces the foe to follow the duo to Never-Ever Land.'),
(2932, 'Mantis Dance', NULL, 'Transforms the Mantis Arm while whirling violently like it was dancing, chopping up the opponent in a certain-kill sword performance until there''s nothing left.'),
(2933, 'Smokin'' Boogie', NULL, 'Shoots out rainbow-colored fumes and shells in all directions from the Punpun Armor, inflicting damage on the opponent while keeping itself hidden.'),
(2934, 'Mantis Arm', NULL, 'Throws the Mantis Arm at the opponent.'),
(2935, 'Ninpou: Fuujinha', 'Ninja Art: Fūjin''s Waves', 'Releases a powerful wave of wind with a move of his arms.'),
(2936, 'Digi Ninpou: Inja Fukkatsu', 'Digi Ninja Art: Hermit Restoration', 'Using talismans, it undoes a seal.'),
(2937, 'Digi Ninpou: Kawarimi no Jutsu', 'Digi Ninja Art: Body Replacement Technique', 'Instantly switches places with a Tuwarmon-shaped dummy.'),
(2938, 'Digi Ninpou: Kumo Shibari', 'Digi Ninja Art: Spider Bind', 'Creates a spiderweb to capture its target.'),
(2939, 'Digi Ninpou: Furoshiki Dzutsumi', 'Digi Ninja Art: Furoshiki Wrapping', 'Traps the opponent in wrapping cloth.'),
(2940, 'Digi Ninpou: Kawashimi no Jutsu', 'Digi Ninja Art: Body Dodging Technique', 'Moves at speeds high enough to look as if it was teleporting.'),
(2941, 'Healing Therapy', NULL, 'Makes the opponent''s fighting spirit vanish just by caressing their head. Hotan heals Venusmon and its allies, then increases their attack''s powers.'),
(2942, 'LOVE YOU', NULL, 'Blows a kiss that makes the opponents who receive it fall over from the shock.'),
(2943, 'Peace Fantasia', NULL, 'Has Olive prick the opponent in the head, making it have peaceful intentions no matter what kind of ferocious personality it has. Throws Olive at the enemy.'),
(2944, 'Bomber Art', NULL, 'Radiates flames to use for welding.'),
(2945, 'Pinpoint Weapon Works', NULL, 'Uses its "Bomber Art" and manufactures then and there an appropriate weapon to fit the situation.'),
(2946, 'Appropriate Works', NULL, 'Manufactures weapons by performing "Pinpoint Weapon Works" one after another, then equips them to each of its arms in order to fully unleash all of its power.'),
(2947, 'Wing Spiral Shredder', NULL, 'Rotates at high speed to shred the opponent to pieces with its Tail Anchor..'),
(2948, 'Fire Vortex Men', NULL, 'Spins with its shinai while leaving a fire trail from it, then strikes at the enemy''s head.'),
(2949, 'Burning Hammer', NULL, NULL),
(2950, 'Weiß Spirale', 'Deu: White Spiral', 'Pierces any enemy with the Sturm Stinger.'),
(2951, 'Schwarz Nagel', 'Deu: Black Nail', 'Tears the enemy to pieces with the Zasshu Shield.'),
(2952, 'Snipe Headshot', NULL, 'Shoots an arrow through the opponent''s head.'),
(2953, 'Arrow Lance', NULL, 'Fires arrows from its hands.'),
(2954, 'Bow Cutter', NULL, 'Slashes with the bow on its side as if it were a blade.'),
(2955, 'Foot Shot', NULL, 'A trick-shot that fires arrows from its feet.'),
(2956, 'Turbulence Arrow', NULL, 'Fires a random flurry of arrows from its arm without missing a single shot.'),
(2957, 'The World Shot', NULL, 'Concentrates energy in Indra, then uses its body as a bow, firing Indra through a hole that opens in its abdomen.'),
(2958, 'Plasma Railgun', NULL, 'Restrains the enemy with the Plasma Railgun on its right hand.'),
(2959, 'Trident Fang', NULL, 'Chops up the enemy with a single blow from its claws.'),
(2960, 'Hyper Launcher', NULL, 'Fires a long-range, high-power energy shot.'),
(2961, 'Zeke Flame', NULL, 'Spews hellfire from its mouth.'),
(2962, 'Final Strikes', NULL, 'Charges while enveloped in light, stabs the oppponent with its claws, and releases energy at point-black range to atomize them.'),
(2963, 'Destroy Smasher', NULL, 'Spins around very rapidly, firing from the gun on its tail in all directions.'),
(2964, 'Zeninage', 'Coin Toss', 'Tosses a fellow Zenimon at the enemy.'),
(2965, 'Snipe Sting', NULL, 'Precisely attacks the opponents vitals with its sword.'),
(2966, 'Twinkle Shoot', NULL, 'Throws its sword, which seeks out the opponent until it lands a blow.'),
(2967, 'Midnight Fantasia', NULL, 'Manipulates young, sleeping digimon nearby by whistling.'),
(2968, 'Giga Tempest', NULL, NULL),
(2969, 'Raptor Grapple', NULL, 'Grabs the foe and lifts them high in the air, then dives down and flings them to the ground.'),
(2970, 'Kouyouhoujou: Kamon no Jin', 'Kouyouhoujou: Whirlpool Formation', 'Raises a waterspout by freely spinning its astonishing super-heavyweight class Kouyouhoujou staff.'),
(2971, 'Kouyouhoujou: Taki no Jin', 'Kouyouhoujou: Waterfall Formation', 'Strikes the ground with its staff to shatter it and release a raging current.'),
(2972, 'To Shishun-kyou', 'Dù Zichūn Sutra', 'Brings the hearts of wild Digimon back to their senses by making them listen to endless words of gratitude.'),
(2973, 'Kochoumu-kyou', 'Butterfly Dream Sutra', 'Manifests the ordeals that it has suffered and showers them on the opponent.'),
(2974, 'Mugen Danmakushin-kyou', 'Endless Barraging Heart Sutra', 'Displays an illusion that its scattered rosary beads are endlessly attacking the opponent from all directions in order to crush their spirit.'),
(2975, 'Grand Heat Storm', NULL, NULL),
(2976, 'Free Death Fall', NULL, 'Continuously displays illusions of being knocked to the ground 10,000 times.'),
(2977, 'Kill Me', NULL, 'Manipulates the surrounding Digimon to assault the enemy who is being haunted.'),
(2978, 'Satori Henro Shou', 'Enlightened Pilgrim Palm', 'Enlightens those who challenge it to battle that conflict is meaningless by having them endlessly fight against an illusion on top of its palm, so in the end both their mind and body are exhausted.'),
(2979, 'Reikou-Kumo-no-Ito', 'Light of the Spider''s Thread', 'Purifies and remedies evil by illuminating the opponent with a halo that cannot be shut out even if they close their eyes.'),
(2980, 'Taijou Shingon', 'Mantra of Neglect', 'Crushes hostility with a thundering voice, knocking the opponent away beyond the horizon.'),
(2981, 'Dynamite Soul', NULL, 'Rekindles the weakened hearts of dispirited Digimon by shouting passionate phrases at them.'),
(2982, 'Astro Bomber', NULL, 'Turns into a flaming star that creates a huge crater when it falls to earth.'),
(2983, 'Ryūsei Rock Damashī', 'Meteor Rock Spirit', 'Shoutmon EX6 fires Shooting Starmon at the enemy with a straight punch.'),
(2984, 'Brave Beat Rock Double Xros', NULL, 'Fuses OmegaShoutmon''s red flames and ZekeGreymon''s blue flames, clothes its body with hellfire that purifies all corruption, and assaults the opponents like a meteor, vaporizing them.'),
(2985, 'Electric Buster Xros', NULL, 'Fires spheres of electricity from the Electric Buster Xros on its right arm.'),
(2986, 'Trident JusFang', NULL, 'A powerful blow from the claws of the Trident JusFang on its left arm. Slashes with the blades on its right arm.'),
(2987, 'Hyper Rock Magnum', NULL, 'Fires homing bullets of flame from the Trident JusFang.'),
(2988, 'Sol Calibur', NULL, 'Slashes with the blade on its right wrist.'),
(2989, 'Demolition Horn', NULL, 'Unleashes a devastating punch with the drill on its left wrist.'),
