(2995, 'Victory Spear', NULL, NULL),
(2996, 'Cosmo Victory', NULL, NULL),
(2997, 'Helio Slasher', NULL, 'Soars towards the opponent and cuts them to pieces while burning them to cinders with a single brandish.'),
(2998, 'Space Chakram', NULL, 'Launches a ring-shaped vacuum blade to cut the opponent to pieces.'),
(2999, 'Xros Shooting Rocker', NULL, 'Sets its McField-brand mic on fire, then swings it down on an enemy, causing an explosion in the face of Xros Heart''s logo.'),
