INSERT INTO habilidades (id, nome, traducao, descricao) VALUES
(3001, 'Double Flare Buster', NULL, 'Shoots all of its energy from the Zanahoria in its left hand.'),
(3002, 'Seven Victorize', NULL, 'Concentrates its entire aura in its chest and fires it from its "V".'),
(3003, 'All Omega the Fusion', NULL, 'Covers itself in an Omegamon-shaped aura then charges in.'),
(3004, 'Seven Victorize Maximum', NULL, 'Concentrates its entire aura in its chest and fires it from its "V", along with six other "V"s.'),
(3005, 'Final Xros Blade', NULL, 'Slashes its McField-brand mic, which has been transformed into a greatsword by concentrating energy, downward from overhead. This technique only harms Digimon with evil hearts, and resets the data of such Digimon and reduces them to Digitamas.'),
(3006, 'Giga Heartbreak Attack', NULL, 'Attacks with an electrified heart of pink energy.'),
(3007, 'Kiendan', 'Oni Fire Bullet', 'Shoots a fireball from its mouth.'),
(3008, 'Ginkaku Tokkan', 'Silver Horn Rush', 'Capitalizes on its large build by lowering its back and charging to crush the opponent.'),
(3009, 'Kin Gin Raimeigeki', 'Gold Silver Thunderclap Attack', 'Exposes the opponent to high voltage when Kinkakumon is aboard in a further addition to the Ginkaku Tokkan.'),
(3010, 'Gyakugeki Endan', 'Reverse Attack Fire Bullet', 'Fires off the Kiendan while stepping back from an opponent that has challenged it in close combat.'),
(3011, 'Hiden Kibakuha', 'Fire-Electric Oni Explosive Wave', 'Unleashes a combined attack using Kinkakumon''s electricity and Ginkakumon''s hellfire.'),
(3012, 'Higi: Mugenei', 'Secret Technique: Waking Shadow', 'Deftly handles the Nyoikinkobou and makes sport of the enemy with its acrobatic movements, unleashing an attack of afterimages that makes it look like the opponent is under attack by a horde of Gokuwmon.'),
(3013, 'Shippūjinraigeki', 'Lightning-speed Attack', 'Pierces the Nyoikinkobou into the ground and extends it to a thundercloud in the sky, then accumulates the thunder energy within itself, and rams the opponent like a bolt of thunder.'),
(3014, 'Choutaiden Raikouhou', 'Super-electrified Lightning Cannon', 'Amplifies and fires the energy within the Nyoikinkobou.'),
(3015, 'Kintoun', 'Somersault Cloud', 'Gathers clouds and flies through the sky at high speeds.'),
(3016, 'Sol Blaster', NULL, NULL),
(3017, 'Octa Gravity', NULL, NULL),
(3018, 'High Gravity Pressure', NULL, 'Wraps its hands about the opponent and compresses them.'),
(3019, 'Gravity Bang', NULL, 'Concentrates the Digital World''s gravity either on itself or in the form of an object of solid energy, then detonates all that energy.'),
(3020, 'Gigas Spiral', NULL, 'Charges the enemy with the Drill Lance.'),
(3021, 'Hell Incinerate', NULL, 'Incinerates the enemy with a giant tornado of flames.'),
(3022, 'Death Destroyer', NULL, 'Fires dark shots from the two cannons on its back.'),
(3023, 'Ran-gum Break', NULL, 'Randomly flails its Shippodzuchi in all directions.'),
(3024, 'Jacked Hammer', NULL, 'Swings down its super-sized Shippodzuchi while jumping or performing a forward handspring.'),
(3025, 'Fire Vortex', NULL, 'Strikes a single blow with its Shippodzuchi while performing continuous somersaults at speeds that generate flames.'),
(3026, 'Shippodzuchi', 'Tail Hammer', 'Attacks with its Shippodzuchi.'),
(3027, 'Deneireppa', 'Film Buster', 'Turns the power of its enemy''s attacks into particles.'),
(3028, 'Koudensappou-no-Jin', 'Formation of Photoelectric Execution', 'Synchronizes surrounding Monitamon with itself, allowing it to use them as extensions of itself.'),
(3029, 'Itenkou', 'Healing Sky Light', 'A healing technique.'),
(3030, 'Goukadan', 'Hellish Fire Shot', 'Shoots a fireball from the tip of its Denji-maru.'),
(3031, 'Bakusuiryū', 'Explosive Water Dragon', 'Shoots a small waterspout from its Denji-maru.'),
(3032, 'Boufūsha', 'Storming Wind Wheel', 'Twirls its Denji-maru to create a tornado.'),
(3033, 'Raidenjin', 'Thunderous Lightning Flash', 'Fires a lightning bolt from its Denji-maru.'),
(3034, 'Shunsakuteki', 'Instant Reconnaissance', NULL),
(3035, 'Final Traveler', NULL, 'Detonates the Fernandina grenade it wears in a suicide attack.'),
(3036, 'Galápagos Field', NULL, 'Spins the weapons in its hands to generate either a wave that slices the enemy or a sound wave that immobilizes them.'),
(3037, 'Timoniniser', NULL, 'Fires bullets embedded in its Gunsword that can cause a variety of different effects.'),
(3038, 'Ouroboros Gate', NULL, 'Draws a circular trail at high speed and summons the "Jashin Ouroboros" from it to sink the opponent into hell.'),
(3039, 'Spicy Hard Love', NULL, 'Fires a "Random Laser" barrage all over and sweeps away enemies with its "Medullia".'),
(3040, 'Sexy Dynamites', NULL, 'Slams its bottom into the enemy, causing an explosion of hearts that makes the enemy swoon.'),
(3041, 'Kibakusou', 'Oni Explosive Funeral', 'Swings the Shichisei Kanabou from overhead and pulverizes the whole ground.'),
(3042, 'Dokidokidokyūn', 'Anger-mind Anger-Oni Angry-Moxibustion(Thump-Thump-Thump)', 'Discharges a high-tension current from its whole body as an all-purpose technique that excels in offense and defense.'),
(3043, 'Raikou Kishū', 'Lightning Oni Kick', 'Attacks with a lightning-speed, surprise kick that conceals an electric shock to paralyze the opponent.'),
(3044, 'Wise Sword', NULL, 'Hurls a wave of blue energy from the Wise Sword.'),
(3045, 'Icchi Dan Ketsu', 'Strength in Solidarity', 'All Kozenimon attack the enemy together.'),
(3046, '¥UE-N', NULL, 'All Kozenimon create a shock wave by crying out.'),
(3047, 'Tail Anchor', NULL, NULL),
(3048, 'Blaze Spiker', NULL, 'A blazing shōtei-uchi.'),
(3049, 'Tekken Seisai', 'Striking With Fists', 'Both Gankoomon and Hinukamuy unleash a barrage of punches.'),
(3050, 'Jishin! Kaminari! Kaji! Oyaji!', 'Earthquake! Lightning! Fire! Father!', 'Summons an earthquake, lightning bolts and an eruption of fire, then Hinukamuy deals a hammer-like punch.'),
(3051, 'Chabudai Gaeshi', 'Flipping the Chabudai', 'Grabs the ground and upends it like a chabudai as hard as Chrome Digizoid.'),
(3052, 'Lightening Feel', NULL, 'Makes the immediate future bright for anyone with a pure heart in its vicinity.'),
(3053, 'Lumina Flash', NULL, 'Dazzles the enemy with the lumens it has accumulated in the ring on its head.'),
(3054, 'Prism Maverick', NULL, NULL),
(3055, 'Infinity Prism Garrett', NULL, 'Turns its drills into burning energy which bore through the enemy.'),
(3056, 'Heavy the Shot', NULL, 'Shoots a beam from the gun on its torso.'),
(3057, 'Dorulu Checkmate', NULL, 'Shoots a tornado with beams in it by spinning its tail-drill.'),
(3058, 'Sexy the Cannon', NULL, 'Shoots a beam from the fused Medullia/Berenjena SDX after enlarging it.'),
(3059, 'Rock Damashī Arrow', NULL, NULL),
(3060, 'Oxygen Sorrow Blue', NULL, 'Fires an oxygen-powered blast of wave energy.'),
(3061, 'Digi Ninpou: Hoshi Arashi', 'Digi Ninja Arts: Star Storm', 'Throws several star-shaped shuriken.'),
(3062, 'Beniazuma Straight', NULL, 'Uses its right fist to deliver a strike packed with all of its power.'),
(3063, 'Beniazuma Uppercut', NULL, 'Uses its left fist, packed with piping hot steam, to strike the enemy and send them flying together with the rising heat.'),
(3064, 'Akumu no Awa', 'Nightmare Bubble', NULL),
(3065, 'Gypt Ryūshi Hou', 'Gypt Particle Cannon', 'Emits the Gypt Particles generated within its large wicked sphere to the entire surroundings, and if anyone touches them even slightly, they will spread throughout their entire body and completely erase them without leaving any data behind.'),
(3066, 'Ruin Blast', NULL, 'Pours Gypt Particles inside a seized enemy''s body through its tentacles, and causes them to explode from within.'),
(3067, 'Copy', NULL, 'Quickly creates copies of itself or Digimon it has absorbed.'),
(3068, 'Divine Pierce', NULL, 'Pierces the opponent with the Cross Barbée. Fires a yellow beam of energy from the tip of the Cross Barbée.'),
(3069, 'Protect Wave', NULL, 'Generates a protective wave by stabbing the Cross Barbée''s butt end into the ground.'),
(3070, 'Grand Sister Cruz', NULL, 'Performs a coordinated attack with Sistermon Noir.'),
(3071, 'Cross Barbée', NULL, NULL),
(3072, 'Mickey Bullet', NULL, 'Rapidly fires bullets from both Anthony guns at random directions.'),
(3073, 'Bless Fire', NULL, 'Rapidly fires bullets from both Anthony guns in a straight line.'),
(3074, 'Anthony', NULL, NULL),
(3075, 'Fif Slash', NULL, 'Cuts the opponent to pieces with its sturdy claws.'),
(3076, 'Teen Ram', NULL, 'Rotates its tail like a drill and thrusts it into the opponent.'),
(3077, 'Lunatic Slash', NULL, 'Hunts the enemy down with its scythe, which can hurl energy blades.'),
(3078, 'Gaia Magicar', NULL, 'Activates a magic circle beneath the enemy that fires a beam upwards, erasing them completely.'),
(3079, 'Lightning Pile', NULL, 'Forms a pile out of lightning and impales the enemy with it from overhead, driving them into the ground.'),
(3080, 'Bolt Break Knockdown', NULL, 'Rushes in and attacks with fists shrouded in lightning from its horn.'),
(3081, 'Charging Strike', NULL, 'Uses its leg strength for a high speed charge that stabs the opponent''s head with its horn.'),
(3082, 'Penetra-laser', NULL, 'Fires a beam from the fingertips of its Mechanization Powered Arm.'),
(3083, 'Powered Ignition', NULL, 'Gathers energy in the palm of the Mechanization Powered Arm while it''s attached, then releases it in a single charge.'),
(3084, 'Bramble Bite', NULL, 'Changes the thorns at the end of its Buster into an evil spirit that bites the enemy.'),
(3085, 'Plant Zone Cradle', NULL, 'Fires thorns from all over its body in all directions.'),
(3086, 'Attract Echo', NULL, 'Plays a song with its Syrinx that makes listeners lose their sense of self and see only Aegiomon.'),
(3087, 'Iron Trust', NULL, 'A backwards kick with its prided goat legs.'),
(3088, 'Stun Beat Blow', NULL, 'Beats up its opponent while releasing eletricity from its arms that numbs them and dulls their movements.'),
(3089, 'Destruction Trigger', NULL, 'Stomps on the opponent, then fires an explosive bullet from its legs at point-blank range.'),
(3090, 'Misery Bullet Rain', NULL, 'A barrage of energy bullets from its fingers followed by a barrage of live ammunition from its entire body.'),
(3091, 'Cook of the Hell', NULL, 'Wraps up the opponent in both of its hands, transforming their configuration data into drinking snacks, and then eating them.'),
(3092, 'Party of the Heaven', NULL, 'Refines alcohol mixed with deadly poisons that cause sleep or paralysis within its body, then pours it over the opponent to incapacitate them.'),
(3093, 'Reverse of the Dead', NULL, 'Fires the data it has consumed from its abdominal mouth as a destructive beam when it becomes too intoxicated and the patterns on its body turn pale.'),
(3094, 'Fly Bullet', NULL, 'Homes in on the enemy''s vitals with the "Fly Bullet" fired from the Rizoma de Loto.'),
(3095, 'Hurricane Screw Shot', NULL, 'Wildly fires the guns hidden in the heels of its boots with a keen Senpukyaku.'),
(3096, 'Rizoma de Loto', 'Esp: "Lotus Root"', NULL),
(3097, 'Inferno Divide', NULL, 'Bites the opponent using the jaws on its hands and fires flaming bullets at point-blank range.'),
(3098, 'Cerberus Erase', NULL, 'Slices the opponent up using the claws on its legs.'),
(3099, 'Famis', 'Lat: "Hunger"', 'Freely manipulates plants to absorb all of the opponent''s energy.'),
(3100, 'Fruits Flechette', NULL, 'Scatters the highly poisonous, unripe fruit from the "Karpos Hulē" over a wide range, transforming its surroundings into a land of death with poison upon impact.'),
(3101, 'Island Freefall', NULL, 'Slams its huge body against the opponent, inflicting damage from the intense shock wave and vibrations around the area where it falls.'),
(3102, 'Burning Blood Shell[N 1]', NULL, 'Fires a magma bodily fluid from its mouth as an enormous flame shot.'),
(3103, 'Phales', NULL, 'Attacks the enemy with vines, poisoning them and draining their health.'),
(3104, 'Chaos Triangular', NULL, NULL),
(3105, 'Bind Red Trigger', NULL, 'Stabs the opponent with the tiny machine guns on the ends of the magazines extending from its hips, immediately destroying them from within.'),
(3106, 'Happy Bullet Showering', NULL, 'Soars into the air and showers the opponent with live ammunition and plasma shots from the guns of its legs and fingers.'),
(3107, 'Konpaku Shingeki', 'Soul Core Attack', 'Slices through both the armor and body of the enemy in a single slash of the Zanjintou, with enough force to strike their Digicore.'),
(3108, 'Genjin Mukon', 'Traceless Phantom Blade', 'Torments the enemy with hallucinations after being pierced with the Zanjintou, plaguing their spirit with endless suffering until they die.'),
(3109, 'Koou Meigun', 'Dark Army Pact', 'Summons phantom warriors with the skulls on both its arms, creating an immortal army which tramples all enemies.'),
(3110, 'Haggard Cluster', NULL, 'Unleashes the fangs on its chest to release a darkness, that absorbs all substances and vaporizes everything.'),
(3111, 'Chaos Rights', NULL, 'Chews the enemy with the mouths all over its body.'),
(3112, 'Hell''s Gate', NULL, 'Causes a gigantic mouth to appear from the darkness and swallows villains whole, and disassembles those who have been swallowed into scraps of fragmented data.'),
(3113, 'Terror''s Cluster', NULL, 'Extends forth the battery on its back and fires its large-scale electromagnetic cannon.'),
(3114, 'Rust Breath', NULL, 'Spews deep scarlet flames that induce a rusting effect on whatever they touch.'),
(3115, 'Rust Claw', NULL, 'Attacks enemies with its sharp nails.'),
(3116, 'No.1<<Polyphony>>', NULL, 'Sings a song in a high soprano, whose notes suffuse the listener''s heart and numb their free will, leaving them at Sirenmon''s mercy.'),
(3117, 'No.2<<Aria>>', NULL, 'Sings a solemn song in a low bass, which becomes a deep bass frequency wave that flattens the enemy through their semicircular canals, so that they are unable to even stand.'),
(3118, 'No.3<<Canon>>', NULL, 'Attacks the enemy using its singing voice as note-shaped shots, which are said to have the marvellous trait of ricocheting to always strike their targets, even separate enemies.'),
(3119, 'Divine Pierce (Satoru)', 'Divine Pierce (Awake)', 'A more powerful version of Divine Pierce.'),
(3120, 'Protect Wave (Satoru)', 'Protect Wave (Awake)', 'A more powerful version of Protect Wave.'),
(3121, 'Grand Sister Cruz (Satoru)', 'Grand Sister Cruz (Awake)', NULL),
(3122, 'Mickey Bullet (Satoru)', 'Mickey Bullet (Awake)', 'A more powerful version of Mickey Bullet.'),
(3123, 'Bless Fire (Satoru)', 'Bless Fire (Awake)', 'A more powerful version of Bless Fire.'),
(3124, 'Mabolt', NULL, 'Constructs an array of tiny thunder clouds, summoned by exchanging blows with the opponent using the hammers in both of its hands, which automatically looses thunderbolts at those it judges as evil or those who hinder its arbitration.'),
(3125, 'Punish Judge', NULL, 'Engraves a seal on the bodies of the opponents strucks by its hammer, bestowing a reprieve to their punishments unless it decides to carry out the sentence, at which point they''re smote with the thunder of an immense electric current.'),
(3126, 'Wide Plasment', NULL, 'Converts its body into extremely high-voltage plasma, inflicting divine punishment all around itself so that all those who are touched by it are completely disintegrated.'),
(3127, 'Triangler', NULL, 'Chops up the enemy with its three scythes.'),
(3128, 'Plasmadness', NULL, 'Showers the enemy with electric shocks gathered in its hands.'),
(3129, 'Death Dinner', NULL, 'Mounts and preys on the opponent.'),
(3130, 'Lightning Shower', NULL, 'Strikes the enemy by causing countless daggers to rain down upon them from above.'),
(3131, 'Thunder Slash', NULL, 'Combines its daggers with lightning to create a whip-like trail, which it uses to slice enemies apart.'),
(3132, 'Circlet Defense', NULL, 'Expands its impregnable defensive walls to counter the opponent''s attacks by deflecting them, while adding electric sparks to the deflected attacks.'),
(3133, 'Kanshaku Dust', 'Manliness-Wrath Dust', 'Reflects the beam fired from the Kanshakudama in its abdomen off of falling stones, resulting in an attack with a large area of effect.'),
(3134, 'Tenbagaeshi', 'Sky-wave Reversal', 'Grips the enemy in its right hand and hammer-throws them into the distance'),
(3135, 'Yobori Claw Drill', 'World-Excavating Claw Drill', 'Impales the enemy with the gigantic excavator on its left hand, which is capable of pulverising even Chrome Digizoid alloy.'),
(3136, 'Absolute Territory', NULL, 'Tears the enemy to pieces as well as the space around them with its yo-yos.'),
(3137, 'Twin Petal', NULL, 'Unleashes a flashkick with its gorgeous legs.'),
(3138, 'Nightmare Assemble', NULL, 'Pierces the enemy with its yo-yos and absorbs them.'),
(3139, 'Senbon Dokkān', 'Thousand Blasting', 'Hammers out its brotherly Black Hickeys from the Ougon Batto.'),
(3140, 'Bukkomi Otokodama', 'Strike of the Man''s Spirit', 'Extends the prison chains sported on its entire body as it charges towards the enemy.'),
(3141, 'Golden Rush', NULL, 'Uses its favourite clubs Ougon Batto, to beat enemies to a pulp.'),
(3142, 'Ougon Batto', 'Golden Faith/Golden Bats', NULL),
(3143, 'Bloody Finish', NULL, 'Skewers enemies with the drills on both arms.'),
(3144, 'Bakuraiten', 'Explosive Thunderstorm', 'Releases bug-shaped mines that self-destruct when they hit enemies.'),
(3145, 'Redbutt', NULL, 'Headbutts an enemy hard enough to shatter their face.'),
(3146, 'Fif Cross', NULL, 'Slashes with the sharp nails on both hands.'),
(3147, 'Burn Flame', NULL, 'A fire attack that intercepts the enemy with pinpoint accuracy'),
(3148, 'Dragless-spiker', NULL, 'Kicks the enemy with the blades on its legs.'),
(3149, 'Teen Blade', NULL, 'Spins its bladed tail like a whirlwind, cutting the foe.'),
(3150, 'Resist Raid', NULL, 'Skewers through the enemy from a flying kick posture with the blades on its feet.'),
(3151, 'Meteor Flame', NULL, 'Rapid-fires fire shots from its mouth like a machine gun, burning the enemy to cinders.'),
(3152, 'Trident Saber', NULL, 'Assaults the enemy with the three red blades equipped to its tail and arms, relentlessly cleaving them apart whether they''re swathed in Chrome Digizoid or not.'),
(3153, 'Gewaltschwärmer', 'Deu: "Violence Enthusiast"', 'Fires a volley in all directions.'),
(3154, 'Platzenkreuz', 'Deu: "Burst Cross"', 'Pins the enemy to the ground with its feet and shoots them at point-blank range.'),
(3155, 'Der Blitz', 'Deu: "The Blitz"', 'Picks off the enemy''s vitals with the six-chambered revolvers on both of its hands.'),
(3156, 'Tekken Seibai', 'Furrow-sword Judgment', 'Slices the enemy to pieces with the blades on its arms while moving at high speed.'),
(3157, 'Schwertgeist', 'Deu: "Sword Ghost"', 'Uses an omnidirectional counter technique alongside "Atho", "René", and "Por" that meets every enemy attack with their nine blades.'),
(3158, 'OS Generics', NULL, 'Temporarily rewrites its own data to perform actions that transcend the laws of nature. Zigzags in the air, leaving behind afterimages, then slashes the enemy in the shape of an X with the blades on its arms.'),
(3159, 'Un Pour Tous', 'Fra: "One For All"', 'Fires a beam of energy from a triangular shield formed by "Atho", "René", and "Por".'),
(3160, 'Love Basket', NULL, 'Summons thunderclouds to enhance Jupitermon''s power.'),
(3161, 'Needle Hive', NULL, 'Repeatedly stabs the enemy with the katars equipped to both its arms.'),
(3162, 'Grace Lance', NULL, 'Auto-attacks surrounding enemies with its sentient lances.'),
(3163, 'Welcome Lost', NULL, 'Continuously stabs the opponent with the lances on both its arms, destroying their life-force.'),
(3164, 'Lingrudge', NULL, 'Crushes the enemies it captures with the chains covering its whole body after they spit out words of confession.'),
(3165, 'Liar Banishment', NULL, 'Causes a hologram of Jupitermon to appear, instantly vaporizing enemies that lay their eyes upon it.'),
(3166, 'Keraunós Divide', 'Grc: "Lightning Divide"', 'Slashes the enemy with a single swing of the Keraunós it wields with both hands.'),
(3167, 'Lightning Be', NULL, 'Looses thunderbolts to where it points.'),
(3168, 'Dios Thunder', 'Esp: "God Thunder"', 'Drops the Keraunós from high in the sky to cast its final judgment upon defeated sinners.'),
(3169, 'Holy Desire', NULL, 'Destroys evildoers with arrows of light fired from its right arm.'),
(3170, 'Dark Despair', NULL, 'Crushes and deletes captured opponents with its left hand, including their Digicores.'),
(3171, 'Chaos Degrade', NULL, 'Fuses the energy of light and darkness from its arms to produce a gate to another dimension, consigning the enemy to oblivion.'),
(3172, 'X Scratch', NULL, 'Swipes at the opponent with both paws'' claws, forming an X shape.'),
(3173, 'Trichobezoar', NULL, 'Spits out a data-destroying hairball from its mouth.'),
(3174, 'Shut Claw', NULL, 'Scratches the opponent with its sharp claws.'),
(3175, 'Berserk Thinking', NULL, 'Slashes with both arms'' Cursed Claws, forming an X shape.'),
(3176, 'Felt Made', NULL, 'Creates copies of itself with the lures it sends flying from its body.'),
(3177, 'Cursed Claw', NULL, 'Slashes the opponent with the sharp claws projecting out of its armor.'),
(3178, 'Garuru Sword', NULL, 'With the Garuru Sword on the right arm, perform a multi-hit attack.'),
(3179, 'Grey Cannon', NULL, 'With the Grey Cannon on the left arm, perform a multi-hit attack.'),
(3180, 'Volcanic Flare', NULL, 'Spews scorching-hot flames from its mouth.'),
(3181, 'Glide Blaze', NULL, 'Rams the enemy while sending out scorching flames hotter than even magma from its whole body.'),
(3182, 'Petit Flame', NULL, 'Spews out a small, high-temperature flame from its mouth.'),
(3183, 'Plasma Stake', NULL, 'Reinforces its heavyweight grappling with electricity, striking with the "Plasma Stakes" on both arms, which send electric current flowing into even the sturdiest of structures and destroying them from within.'),
(3184, 'Thunder Vernier', NULL, 'Rotates the "Thunder Verniers" on its back to face forward, from which it fires electricity, or uses them while faced backwards to propel it forward.'),
(3185, 'Elec Guard', NULL, 'Releases plasma particles into its surroundings and uses them to erect a barrier around it.'),
(3186, 'Kijū Engetsutou', 'Yellow Beast Crescent Blade', NULL),
(3187, 'Jūrou Daikaiten', 'Great Beast-Wolf Rotation', 'Spins its entire body and attacks the opponent while turning into a blade.'),
(3188, 'Geki: Hyougetsuga', 'Fury: Ice Moon Fang', 'Molds the Kijū Engetsutou into countless forms using ice, and then hurls it at the opponent.'),
(3189, 'Grasslash', NULL, 'Slices the enemy with the blades on both arms.'),
(3190, 'Blindead', NULL, 'Fires a beam attack from its chest, which deals massive damage and carves a ''20'' mark into the enemy if it lands a direct hit.'),
(3191, 'Zwanglänze', 'Deu: "Twenty-Sparkling"', 'Focuses its fighting spirit into the blades on both arms and slices the enemy with them.'),
(3192, 'Thron Messer', 'Deu: "Throne Knife"', 'Spins its body to slice multiple enemies in one fell swoop.'),
(3193, 'Merudainā', NULL, 'Fires a laser-shaped heat ray from its mouth.'),
(3194, 'Wild Blast', NULL, 'Scatters mineral dust by flapping its wings and causes an explosion.'),
(3195, 'Great Flame', NULL, 'Takes a deep breath and spits out the largest fireball it can make.'),
(3196, 'Earth-stamp', NULL, 'Uses its forearms to lunge at and slam onto the opponent.'),
(3197, 'Wall Rake', NULL, 'Uses the Wall Rake it wields on both arms to attack and defend.'),
(3198, 'Modestly Stun', NULL, 'Restrains the enemy with its two appendages, paralyzing them with the stinger on its tail.'),
(3199, 'End of the World', NULL, 'Fires a jet-black wave from its mouth that destroys all data.'),
(3200, 'Magna Visibility', NULL, 'An omnidirectional attack where it launches the two orbs embedded in its wings to attack the enemies around it.'),
(3201, 'Summon Apocalypse', NULL, 'Its falling feathers transform into countless Digimon and attack, bringing terror and despair to not only this attack''s targets, but also all who witness it.'),
(3202, 'Palazzi Valzer', 'Ita: "Palaces'' Waltz"', 'Uses magic to make copies of the "Spiedini" swords its carries on its waist and sends them flying from every direction.'),
(3203, 'Quarzione', NULL, 'Fires bullets from its two "Ala di Pollo" guns that lodge themselves inside the enemy''s body, attacking and annihilating them from within.'),
(3204, 'Road T(w)o Decade', NULL, 'Thrusts straight into the enemy''s chest while shouting "Twentiestttt!!".'),
(3205, 'Vingtième', 'Fra: "Twentieth"', 'Curls its body into a ball and spins towards the enemy, slicing them with its tail blade.'),
(3206, 'Twenty Dive', NULL, 'Charges head-first at the opponent.'),
(3207, '20 Scratch', NULL, NULL),
(3208, 'Form Taranis', NULL, 'Shreds the opponent with its claws and the tip of its tail, injecting impaled opponents with corrosive data.'),
(3209, 'Purhorus', NULL, 'Fires laser bullets from the gemstones on its claw armor and chest armor.'),
(3210, 'Ankokuiki', 'Darkness Zone', 'Slams its claw armor together and fires a barrage of thorns from their gemstones.'),
(3211, 'Knowledge Stream', NULL, 'Freely combines the five elements from the magic circles on both of its arms and releases enormous energy.'),
(3212, 'Sefer Raziel', NULL, 'Brings about any kind of miracle to exterminate the adversary.'),
(3213, 'Sakkuri', 'Cutting Easily', NULL),
(3214, 'Sakusaku', NULL, NULL),
(3215, 'Shirotsume Ichimonji-giri', 'White Clover Horizontal Slash', 'Cuts down the enemy without making a sound by using its cherished sword Shirotsume-Ichimonji.'),
(3216, 'Byakusai', 'White Murder', 'Rapidly throws the two knives it hides within its sleeves.'),
(3217, 'Tohhō', 'Piercing Wasp', 'Stabs the enemies at close range using the knives planted on its feet after letting their guard down.'),
(3218, 'Shirotsume Ichimonji-giri (Satoru)', 'White Clover Horizontal Slash (Awake)', NULL),
(3219, 'Byakusai (Satoru)', 'White Murder (Awake)', NULL),
(3220, 'Tohho (Satoru)', 'Piercing Wasp (Awake)', NULL),
(3221, 'Eclipse Finger', NULL, 'Focuses the amplified energy within its body in the palms of its hands, and melts the enemy by touching them.'),
(3222, 'Calydon Arcus', 'Lat: Calydon Bow', 'Fires the eight "Meleagros" blades it wears on its back to pursue the enemy until they are destroyed.'),
(3223, 'Infinity Dream', NULL, 'Flaps its wings to stir up a gust that spreads its scales. While this attack is capable of inflicting poison or paralysis on the enemy, its main function is actually to ease the pain and suffering of its wounded allies.'),
(3224, 'Fly Bullet: Segundo', 'Esp: Fly Bullet - Second', 'Fires "Fly Bullet" from the Rizoma de Loto across the battlefield endlessly in all directions and attacks with its unpredictable trajectory.'),
(3225, 'Distancia Cero', 'Esp: Zero Distance', 'Finishes the enemy off with a zero-distance shooting attack that the enemy cannot see.'),
(3226, 'Baby Hail', NULL, 'Spits countless icicles from its mouth.'),
(3227, 'Ice Mash', NULL, 'Attacks continuously with the claws on both hands.'),
(3228, 'Guren Storm', 'Crimson Storm', 'Unleashes a blaze from its flaming wings.'),
(3229, 'Blast Smash', NULL, 'Detaches its wings, shrouding itself in a barrier of flame as it charges towards the enemy.'),
(3230, 'Kottsun', 'Knock', 'Pokes at the opponent with the brim of its hat.'),
(3231, 'Hjaðningar Waltz', NULL, 'Spins its Kyūkyoku Senjūken Dáinsleif Dáinsleif at the speed of light, reducing targets within a 3 km radius to ash. Those whose have witness this technique turn into data dust without even realizing that they were "attacked".'),
(3232, 'Kyūkyoku Senjūken Dáinsleif', 'Ultimate-Battle-Crossblade Dáinsleif', NULL),
(3233, 'Grand Gríðr', NULL, 'Removes the blades on both of its arms and throws them as tomahawks.'),
(3234, 'Frozen Claw', NULL, 'Tears the enemy to pieces with the ice claws equipped to both of its arms, and then freezes their wounds.'),
(3235, 'Callous Dimension', NULL, 'Generates a snowsquall which causes everything around it to be frozen in ice, including the enemy.'),
(3236, 'Rewind Abyss 13', NULL, 'The vilest, most wicked curse, invoked when it opens its hidden thirteenth eye, that causes a Digimon to forcibly degenerate at the end of the countdown.'),
(3237, 'Spooky Zapper', NULL, 'Rotates its body like a spinning top, and tears the enemy to pieces with its enormous claws and hidden arms.'),
(3238, 'Fatal Gaze', NULL, 'Absorbs the data of enemies that gaze at the twelve eyes all over its body.'),
(3239, 'Baby Blaze', NULL, 'Spews out flames from its mouth, to be carried by the wind and cover a wider range when attacking.'),
(3240, 'Smash Horn', NULL, 'Charges at the enemy with its ultra-high temperature horns.'),
(3241, 'Lightning Stinger', NULL, 'Skewers the enemy and injecting energy into them that destroys their data.'),
(3242, 'Crimson Slash', NULL, 'Whirls in a continuous slashing attack with both claws.'),
(3243, 'Lord of Fraternity', NULL, 'Expands its sash-blades, which have amassed the power of Knightmon, and tears the opponent apart in a dance-like manner.'),
(3244, 'Noblesse of Rouge', 'Fra: Nobility of Red', 'Locks the enemies'' movements with rose petals generated from the Rose''s Pile Bunker and precisely impales their Digicore with its Rose''s Fencer.'),
(3245, 'Kyūkyoku Sentotsuken Gran Rozerio', NULL, 'Unleashes a shock wave that blows away any and all who stand on the battlefield from its strongest Pile Bunker, Gran Rozerio, formed by combining its shield and sword.'),
(3246, 'Haunted Pilus', 'Lat: Haunted Hair', 'Freely stretches its hair and sets Ulula and Serpens loose.'),
(3247, 'Crazy-go-round', NULL, 'Generates a large tornado of blue flames after performing a powerful horizontal spinning slash.'),
(3248, 'Sanctus Tormentum', 'Lat: Sacred Cannon', 'Fires an energy cannon from the crystal on its shield.'),
(3249, 'Gurei Tou', 'Fear-Tingling Katana', 'With the Grey Sword transformed into the katana on the left arm, performs a multi-hit and long-range attack.'),
(3250, 'Garuru Hou', 'Refined-Lapides Cannon', 'With the Garuru Cannon on the right arm, fires cold air at absolute zero in the form of a laser.')
ON CONFLICT (id) DO UPDATE SET nome = EXCLUDED.nome, traducao = EXCLUDED.traducao, descricao = EXCLUDED.descricao;

INSERT INTO habilidades (id, nome, traducao, descricao) VALUES
(3251, 'Ice Age', NULL, 'Freezes the enemy with its breath.'),
(3252, 'Meteor Hail', NULL, 'Charges from the sky as if it were a giant block of ice.'),
(3253, 'Surtr Brander', NULL, 'Fires arrows of light enveloped in hellfire, burning all to cinders from its Ultimate-Battle-Crossbow Einherjar.'),
(3254, 'Niflheimr Arrest', NULL, 'Absolute zero cold air generated by the sacred "Niflheimr" shields equipped on each pair of its arms that freezes the surface of the ground and causes all vital functions to be brought to a complete halt.'),
(3255, 'Vermilion Vortex', NULL, 'Causes red, drill-shaped spears to protrude from all over its body, annihilating multiple enemies in one go.'),
(3256, 'Giga Crimson Dive', NULL, 'Charges forth while spinning at high speed, attacking with its quills.'),
(3257, 'Dai Bacchi Gū', NULL, 'Enlarges the badge on its chest and hurls it.'),
(3258, 'Frisbicker', NULL, 'Throws the shields on its arms.'),
(3259, 'Assault Claw', NULL, 'Charges at high speed and attacks with its claws.'),
(3260, 'Crimson Breath', NULL, 'An upgraded version of its original Fire Breath. Spews deep crimson flames that are the same color as its body.'),
(3261, 'Crash Rolling', NULL, 'Curls its entire body up and rush forward at tremendous speed, then slices up any enemy that approaches with the ridge on its back.'),
(3262, 'Oshaburi', 'Pacifier', 'Takes in a deep breath and shoots the inhaled air out together with its pacifier in order to intimidate the opponent.'),
(3263, 'Chikuchiku Rolling', 'Prickly Rolling', 'Curls itself into a ball and does a jump-tackle while spinning.'),
(3264, 'Ballet Gun', NULL, 'Fires its sleeve like a cannon, using the large flower petals that dance around it as reflectors. Uses the shots from its sleeve with its reflectors to form a net that imprisons the opponent.'),
(3265, 'Wisselen', 'Dut: Change', 'Sheds scales that latch onto the opponent, making them lose consciousness and become Rafflesimon''s servants.'),
(3266, 'Direct Smasher', NULL, 'Bisects the enemy in a single stroke by cleaving its sword down from a high altitude.'),
(3267, 'Ignition Prominence', NULL, 'Spews extremely high temperature flames from its shield, turning its surroundings into a sea of fire.'),
(3268, 'Duel Edge-Flowsion', NULL, 'Impales the enemy with its sword wreathed in its shield''s flames, completely incinerating and erasing the enemy.'),
(3269, 'Lightning Buster', NULL, 'Generates electricity at high output from its head and uses it to strike the enemy.'),
(3270, 'Rocket Messer', 'Deu: Rocket Knife', NULL),
(3271, 'Taikyokusen', 'Tai Chi Revolution', 'Fires a spinning yin-yang attack that slices up all who come close.'),
(3272, 'Kochōgen', 'Fox-Butterfly Illusion', 'Changes the texture of its surroundings, inviting the enemy into a world of illusions.'),
(3273, 'Konohanasenki-banshou', 'All Forms of the Plum Blossom Warrioress', 'Turns all of the objects around it into countless shikigami, enveloping the enemy in a storm of flowers and annihilating them.'),
(3274, 'Uka-no-Mitama', NULL, 'Fuses its four kuda-gitsune into a single gigantic fox spirit and summons it.'),
(3275, 'Lightning Fur', NULL, 'Shoots lightning-coated quills.'),
(3276, 'Kenzan Dive', NULL, 'Curls its body up into a ball and charges forth.'),
(3277, 'Tekken Danzai', 'Iron-Fist Judgment', 'Pummels the opponent with an iron fist by shooting out its Tactical Arms.'),
(3278, 'Schwertflügel', 'Deu: "Sword Wing"', 'Fires off the swords and continuously slashes at the opponent with its two great-swords.'),
(3279, 'Kyūkyoku Senjin Seibaken', 'Ultimate-Battle-Blade Seibaken (Holy Conqueror Sword)', 'Pulls out its Ultimate-Battle-Blade Seibaken from the Digicore in its chest, then destroys the fighting spirit of any opponent it cuts.'),
(3280, 'Kankan', 'Clanging', 'Strikes at the opponent with the sharp corners of its shield.'),
(3281, 'BB Burner', NULL, 'Releases the flames stored in its mouth in one shot.'),
(3282, 'Grand Holy Arrow', NULL, 'Transfers power from surrounding elements and releases it as a lightning arrow.'),
(3283, 'Seventh Jewelrize', NULL, 'Transforms the enemy''s Digicore that it scoops out with its right hand into a jewel using the Crown of Greed.'),
(3284, 'Seventh Penetrate', NULL, 'Uses the power of the Crown of Sloth to emit a crimson energy wave from each of its claws at maximum power'),
(3285, 'Darkness Prison', NULL, 'Expands the dark globe in its abdomen, eternally trapping the consciousness of anyone who comes into contact with it in darkness.'),
(3286, 'Biririn Hug You', 'Shocking Hug You', 'Hugs evil Digimon that it has given up on, sending an electric shock through their body and reducing them to ashes.'),
(3287, 'Extreme Tailer', NULL, 'Compresses the Vaccine energy charged up in its wings and fires it from its tail.'),
(3288, 'Cruel Tornado', NULL, 'Crushes the opponent with a tornado created by its Vortex-spear.'),
(3289, 'Deadly Break Lost', NULL, 'Splits the opponent apart with a cross-slash with its Cyclone Deathscythe.'),
(3290, 'Flame Snatch', NULL, 'Grabs an enemy with its flaming left claw and burns it.'),
(3291, 'Inferno Burst', NULL, 'Transforms into a blazing demon god enveloped in its Flame Inferno.'),
(3292, 'Seventh Graviton', NULL, 'Fires supergravity lasers from its shoulders and part of its abdomen, erasing all of its surroundings and reducing it to ash.'),
(3293, 'Pendragon Sparkle', NULL, 'Impales the enemy with its fully unleashed "Kyūkyoku Senryūsou Ambrosius", and looses large thunderbolts from its Dragonic Plasma.'),
(3294, 'Raiken Bureiragaha', 'Thunder Sword Bureiragaha', 'Twelve swords appear from the lightning that falls from its Dragonic Plasma, which it fires at the enemy.'),
(3295, 'Kyūkyoku Senryūsou Ambrosius', 'Ultimate-Battle-Dragonlance-Ambrosius', 'A sentient, high-energy lance. The amount of energy it releases varies depending on how strong the opponent is.'),
(3296, 'Kyūkyoku Sengi Tengyouken', 'Ultimate-Battle-Technique-Tengyouken', 'A flawless, pulverizing uppercut that condenses all of its energy in its right hand, ignoring all defenses.'),
(3297, 'Tetsu Geta Harite', NULL, 'Deals heavy blows with its Tetsu Geta.'),
(3298, 'Cauda Mortifera', 'Lat: Deadly Tail', 'Skewers the enemy with its tentacle-shaped tails all at once.'),
(3299, 'Rostrum Triadens', 'Lat: Three-pronged Snout', 'Crunches the enemy with its three split jaws.'),
(3300, 'Seventh Lightning', NULL, 'It unleashes extremely powerful lightning from its three horns once the envy energy contained within it reaches its peak and the Crown of Envy shines, which is said to sink continents into the ocean.'),
(3301, 'Seventh Fascinate', NULL, 'Draws out power from the Crown of Lust to control others over a vast range.'),
(3302, 'Fi-rost Typhoon', NULL, 'A Unison Technique where it inhales air at the exact same time as Terriermon and expels it as a mixture of hot and cold air.'),
(3303, 'Seventh Divine Cruz', 'Esp: Seventh Divine Cross', 'Arranges ten super-heated spheres of light in a cruciform syzygy and fires light of annihilation.'),
(3304, 'Hermannia', NULL, 'A dark incantation shot.'),
(3305, 'Merry Merry Destruction', NULL, 'Unleashes a vast amount of magical power from its umbrella.'),
(3306, 'X-radicate', NULL, 'Burns anything without leaving a trace.'),
(3307, 'Pandemic Destroyer', NULL, 'Fires viral energy in its Blast Mode.'),
(3308, 'Energy Blitz', NULL, 'Flies at critical velocity, and pierces the enemy in its Blitz Mode.'),
(3309, 'Laser Cannon', NULL, 'Annihilates things in a straight line with a powerful beam that it accumulates in the laser gun on its tail. The light that is emitted the moment this technique is invoked can be seen even from places 10 km away, and those who have witnessed it directly at close range are blinded by its overwhelming radiance.'),
(3310, 'Laser Saber', NULL, 'Sets the laser on its tail to being a sword, then charges and slashes with it at high speed.'),
(3311, 'Lovely Splash', NULL, 'Repels the enemy by pouring a large amount of Lovely Gel over them. This technique becomes more powerful as the support for Monzaemon increases.'),
(3312, 'Trick or Treat Wallace', NULL, 'Manifests giant pumpkin-shaped bombs in the air to blow up everything around it.'),
(3313, 'Wassamu Ring Jack', NULL, NULL),
(3314, 'Atlantic Dam', NULL, 'Pours a huge amount of pumpkin soup into the enemy''s body, making them explode. Uses pumpkin soup to put out flames.'),
(3315, 'Unchi Rush', 'Poop Rush', 'Throws a barrage of poop together with its tiny Numemon all at once.'),
(3316, 'Holy Material', NULL, 'Spins the Eden''s Lance, generates a large number of magic circles around it and fires holy light, reducing evil enemies to ashes.'),
(3317, 'Eden''s Lance', NULL, 'A weapon formed by combining the armor on its shoulders.'),
(3318, 'Behead Slasher', NULL, NULL),
(3319, 'Destiny Death Destruction (Death 3)', NULL, 'Transforms its six arms into gigantic spears, and fires beams that erase everything they touch.'),
(3320, 'Flare Rock Damashī', 'Flare Rock Spirit', 'Its passion turns into crystal claws which drastically increases its power.'),
(3321, 'Heavy Heat Vulcan', NULL, 'Rapid-fires tiny fireballs; each shot is Mega Flame-class.'),
(3322, 'Zeal Magnum', NULL, 'Charges its hands with scorching-hot energy shots that never cool down, and then fires them.'),
(3323, 'WEEK END', NULL, 'Swings down its guitar like an axe'),
(3324, 'Vampire Theory', NULL, 'Wraps the enemy in its cape and turns them into a bat.'),
(3325, 'Bloody Drain', NULL, 'Pierces the enemy with the claws on its cape and absorbs their data.'),
(3326, 'Meteorizer', NULL, 'Exterminates evil enemies by charging from the skies at lightspeed.'),
(3327, 'Secret Wall', NULL, 'A barrier that wards off evil in its surroundings.'),
(3328, 'Golden Square', NULL, 'Fires purifying beams from the crystals on its wings and forelegs.'),
(3329, 'Rapid Blaster', NULL, 'Rapid-fires the Armed Arms on its back at long-range, which has a low attenuation rate.'),
(3330, 'Laser Gatling Arm', NULL, 'Rapid-fires the Armed Arms on both of its arms at close-to-mid-range.'),
(3331, 'Billion Bullet', NULL, 'Detaches all of the Armed Arms, cornering the enemy by operating them remotely, and shooting them up with a billion bullets.'),
(3332, 'Gyro Smash', NULL, 'Dishes out a powerful punch while spinning the blades on its arm.'),
(3333, 'Qualialise Blast', NULL, 'Spins its blades at extremely high speed, creating tornadoes that strike the opponent.'),
(3334, 'Spiral Vanish', NULL, 'Shoots out and fuses its spines to form a gigantic drill, which it uses with the emotion energy it has stored to impale the opponent.'),
(3335, 'Spinas Qualialise Blast', 'Lat: Spines Qualialise Blast', 'A stronger version of Qualialise Blast with one arm using the power of Rasenmon: Fury Mode.'),
(3336, 'Desperate Vortex', NULL, 'Extends its large, spiral-shaped tails and skewers the opponent over and over again.'),
(3337, 'Predator''s Bite', NULL, 'Pounces on the opponent, devouring their Digicore directly.'),
(3338, 'Spiral Hell', NULL, 'Indiscriminately attacks by rapidly spinning the blades on its wrists, tearing apart everything in their surroundings while generating tornadoes.'),
(3339, 'Sunrise Buster', NULL, 'Charges its energy to the maximum, and fires it from the Trident Revolver.'),
(3340, 'Zan Thrust', 'Slash Thrust', 'A slash technique that has extraordinary sharpness.'),
(3341, 'Koryūkyū', 'Barbarian-killing Ball', 'Turns into a ball of light and attacks evil.'),
(3342, 'Summon Frost', NULL, 'Spreads cold air over a wide range, instantly transforming anyone that draws near into statues of ice.'),
(3343, 'Absolute Blast', NULL, 'Unleashes an absolute zero wave from the dragon jaws on its left shoulder which shatters everything.'),
(3344, 'Hecto Edge Blizzard', NULL, 'Causes countless ice swords to fall down like a blizzard.'),
(3345, 'Summon Chaser', NULL, 'Summons flame and ice elementals to chase the opponent persistently.'),
(3346, 'Kokon Pick', 'Tap-tapping Pick', 'Peck with its hard beak.'),
(3347, 'Laser Eye', NULL, 'Shoots lasers from its eyes.'),
(3348, 'Sonic Vulcan', NULL, 'Fires high-speed machine guns from its shoulders.'),
(3349, 'Messer Spiral', 'Deu: Knife Spiral', 'Charges while spinning at high speed.'),
(3350, 'N.S.B.M', NULL, 'Intercepts the enemy with a laser fired from its tail, even if they get behind it.'),
(3351, 'Seiken Meppa', 'Sacred Fist Destroyer', 'Unleashes a subluminal combo-attack that succeeds Gankoomon''s secret technique'),
(3352, 'Knights'' Intruder', NULL, 'Becomes a vessel for the fourteenth Ultimate-Battle-Blade that should not exist, by concentrating the energy of the Royal Knights, turning into an offensive judgment sword that instantly erases the opponent no matter how strong they are.'),
(3353, 'Justice X Kick', NULL, 'Performs a jump kick with its Accel Leg which is said to reach 100 tons in destructive force.'),
(3354, 'Justice X Punch', NULL, 'A punch unleashed from its Blitz Arm.'),
(3355, 'Justice X Blade', NULL, 'Cuts the enemy with its Critical Arm.'),
(3356, 'Gräme', 'Deu: "Grieve"', 'Destroys the enemy''s body from within using its chain.'),
(3357, 'Ende Brechen', 'Deu: "End Break"', 'Crushes the enemy''s Digicore directly with its Zerdrücken.'),
(3358, 'Gaze Eraser', NULL, 'Fires cursed beams from all of the eyes on its tentacles.'),
(3359, 'Gala-lightness', NULL, 'Seizes the enemy with its tentacles and swallows them whole with its central mouth.'),
(3360, 'White Liner', NULL, 'Fires a white beam from its central mouth.'),
(3361, 'Strash Salamander', NULL, 'Uses the spear on its tail as a weapon and skewers the enemy with it.'),
(3362, 'Red Reamer', NULL, 'Burns the enemy with high-intensity red lasers emitted from the tips of its claws.'),
(3363, 'Gaia Brave', NULL, 'Converts the flames of courage contained within it into an ultra-high temperature energy shot and then releases it.'),
(3364, 'Agumon''s Courage', NULL, 'Increases the power of its, and its allies'', attacks.'),
(3365, 'Brute Knuckle', NULL, 'Curls up the tentacles on its arms into balls and punches with them.'),
(3366, 'Volt Line', NULL, 'Sends an electric shock through the enemy.'),
(3367, 'Mount Stone', NULL, 'Hurls the rocks on its arms.'),
(3368, 'Glide Rocks', NULL, 'Strikes the enemy with its rock-covered tail at tremendous speed.'),
(3369, 'Psychic Chain', NULL, 'Constricts the enemy with psychokinetic chains, and drives them away.'),
(3370, 'Cloud Vision', NULL, 'Spews out clouds that cause hallucinations.'),
(3371, 'Minimal Flash', NULL, 'A static electricity-laced tackle.'),
(3372, 'Raigekishou', 'Lightning Heel', 'Lands an axe kick into the opponent''s skull with lightning.'),
(3373, 'Budenhadan', 'Buden Blast', 'Fires oversized energy shots from its held-out palms.'),
(3374, 'Jinrai Kaitengeki', 'Storm of Blows', 'Dishes out a series of kicking and punching techniques without giving the opponent a chance to strike back.'),
(3375, 'Electrical Fist', NULL, 'Sends the enemy flying with a blow from its electricity-laced fist.'),
(3376, 'Thunder Dread', NULL, 'Unleashes an electric attack by discharging the electrical energy stored in its horn.'),
(3377, 'Core Electrical Fist', NULL, 'A stronger version of Electrical Fist, powered up by the energy of Bulkmon''s Digicore.'),
(3378, 'Dark Wing', NULL, 'Flaps its tattered wings, causing dark bullets to rain down.'),
(3379, 'Seidenki', 'Static Electricity', 'Emits static electricity from the tip of its horn.'),
(3380, 'Destroy Claw', NULL, 'Pierces the opponent''s entire body.'),
(3381, 'Mias-spew', NULL, 'Crushes the opponent with its two arms, which materialize as a result of its overflowing negative data.'),
(3382, 'Dryad Stinger', NULL, 'Skewers the enemy with its sharp stake-like tusks.'),
(3383, 'Blasted Disaster', NULL, 'Spews a black miasma consisting of countless tiny insects that thrive on the opponent''s data, causing them to completely wither up.'),
(3384, 'Mirror Guard', NULL, 'Spreads its panel-shaped wings to protect itself or the target.'),
(3385, 'Mirror Dust', NULL, 'Detaches its panel-shaped wings and sends them flying at the enemy.'),
(3386, 'Bolt Rip', NULL, 'Mixes its scales with electric shocks gathered in its palms and fires them at the enemy.'),
(3387, 'Beat Press', NULL, 'Crushes the enemy with its gigantic hands.'),
(3388, 'Hexa-thunder', NULL, 'Unleashes an electric attack from its antennae.'),
(3389, 'Cutting Edge', NULL, 'Throws the panel-shaped energy in its hands to slash the enemy.'),
(3390, 'Aurora Stream', NULL, 'Fires a beam from its chest.'),
(3391, 'Cruelty Rain', NULL, 'Enlarges the panels that it protects itself with, causing them to rain down over the enemy, crushing them.'),
(3392, 'Insec Mind', NULL, 'A telepathic ability that manifests using its antennae as a medium.'),
(3393, 'Defibrilla-shock', NULL, 'Touches the opponent with its palms, which act as positive and negative electrodes, delivering an electric shock.'),
(3394, 'Janengan', 'Wicked Thought Eye', 'Cursed beams fired from all of its eyes.'),
(3395, 'Gugen', 'Deceptive Illusion', 'Transforms the data it has accumulated into objects and uses them both offensively and defensively.'),
(3396, 'Kageshibari', 'Shadow Bind', 'Enters the enemy''s shadow and controls its movements.'),
(3397, 'Full Metal Machine Gun', NULL, 'Causes a downpour of iron to rain down from the Cowl Parts on its arms.'),
(3398, 'Cool Edge', NULL, 'Purges the Cowl Parts and unleashes an instant attack.'),
(3399, 'Moon Tense', NULL, 'Fires laser beams in all directions.'),
(3400, 'Raddle Star', NULL, 'Tracking weapons equipped with AI.'),
(3401, 'Gabumon''s Friendship', NULL, 'Increases the critical hit rate of its, and its allies'', attacks.'),
(3402, 'Full Throttle Edge', NULL, 'Tears the enemy to pieces with the blades protruding from various parts.'),
(3403, 'Madness Fire', NULL, 'Indiscriminately shoots with the four gun muzzles mounted to the sides of its front wheel.'),
(3404, 'Trinity Gospel', NULL, 'Fires energy shots from the three mouths on its head and arms.'),
(3405, 'Acid Injection', NULL, 'Skewers the enemy with its three tails and injects a strong acid into their body.'),
(3406, 'Poseidon Vortex', NULL, 'Generates a large whirlpool by rapidly spinning its whole body.'),
(3407, 'Aqua Viper', NULL, 'Vaporizes its surroundings with a massive amount of energy released from the tip of its horn.'),
(3408, 'Positron Blaster', NULL, 'Concentrates energy into the "Alterous" and fires subluminal bombardments.'),
(3409, 'Alter Blade', NULL, 'Converts the energy it has accumulated into a positron blade.'),
(3410, 'Dead Shot', NULL, 'The weapon on its left arm which also loaded from the Digimon it has sealed. Its power has dropped dramatically due to the data being compressed.'),
(3411, 'Hinder Miasma', NULL, 'Deprives the enemy of their freedom with the mist released from its cage.'),
(3412, 'Gouenrin', 'Roaring Flame Wheels', 'Fires its blazing wheels along with a gust of wind.'),
(3413, 'Kaijinraidou', 'Ash and Thunderclap Eye', 'Strikes down the enemy with lightning that never misses, unleashed from its eye.'),
(3414, 'Kyouka Suigetsu', 'Resounding Scent Water Moon', 'Heals injuries received in battle with the element of water.'),
(3415, 'Rinrin Therapy', 'Intense/Scales Therapy', 'Fluttering scales shaken off of its wings that have the effect of soothing the mind and body, or conversely, paralyzing the body, and are used for different purposes depending on the opponent.'),
(3416, 'Paralyze Lick', NULL, 'Uses its tongue, which secretes a numbing venom, to lick.'),
(3417, 'Downer Eye', NULL, 'Makes the enemy Digimon prey on themselves with the curse of its "Downer Eye".'),
(3418, 'Annihilention', NULL, 'Fires red-hot beams from its eyes.'),
(3419, 'Rudiment', NULL, 'Condenses the energy within its body, and breathes it out of its mouth in the form of a wave.'),
(3420, 'Scissors Sword', NULL, 'Splits any enemy in two with the sword on its right arm.'),
(3421, 'Beetle Cannon', NULL, 'Shoots at the enemy with a volley fire using the weapon on its left arm.'),
(3422, 'Grit Nail', NULL, 'Transforms its forelimbs to being claw-shaped and scratches with them.'),
(3423, 'Sand Blast', NULL, 'Shaves off the enemy''s body with sand that it spits out aggressively.'),
(3424, 'Suckerfish Darts', NULL, 'Fires organic missiles from its abdomen to slow down its prey.'),
(3425, 'Flying Finish', NULL, 'Unleashes a high-speed slash attack with its sharp fins to finish off its prey.'),
(3426, 'Petally Carnage', NULL, 'Disperses a large amount of explosive pollen from the petals around its neck.'),
(3427, 'Tropical Venom', NULL, 'A gas spewed out of its mouth which causes those who inhale it to melt into mush from within.'),
(3428, 'Kaus-slugger', NULL, 'Emits sharp blades from the Sagittarius that head towards the enemy as they form an arc.'),
(3429, 'Alnas Shot', NULL, 'A double laser cannon that accurately picks off the enemy''s vitals.'),
(3430, 'Palsy Sweet', NULL, 'Spews a numbing gas out of its mouth, depriving invading enemies of their freedom.'),
(3431, 'Wavy Oktavist', NULL, 'Emits a super-low-pitched cry that crushes even rocks at a loud volume, and engulfs several tens of meters around it in a whirlpool of destruction.'),
(3432, 'Cruel Invite', NULL, 'Drags its target underwater by impaling them with its caudal fin, which is sharpened like a fish hook.'),
(3433, 'Calamity Vise', NULL, 'Rapidly oscillates as it gnaws through its prey, puncturing their body, killing them.'),
(3434, 'Rapid Seed', NULL, 'Spits out countless seed-like bullets from its mouth.'),
(3435, 'Fruits Rush', NULL, 'Curls up and speeds off.'),
(3436, 'Elec Rush', NULL, 'Rams into the enemy with all its might at lightning speed.'),
(3437, 'Petit Impulse', NULL, 'Discharges electricity generated within its body from its hair.'),
(3438, 'Vanquish Missile', NULL, 'Fires a large quantity of missiles from its left arm.'),
(3439, 'Maximum Demolisher', NULL, 'Pulverizes the enemy''s body as it minces them with the heavy machinery on its right arm.'),
(3440, 'Briona Strike', NULL, 'Pierces the enemy with the sword in its right hand, accompanied by a flash of lightning.'),
(3441, 'Reactor Discharge', NULL, 'Blows away everything around it, including seawater, with plasma discharged from its pincer.'),
(3442, 'Lightning Rush', NULL, 'Charges the enemy at super speed from their blind spot.'),
(3443, 'Heartbeat Impulse', NULL, 'Shoots energy blades from its tail that slice enemies apart.'),
(3444, 'Refuge Mist', NULL, 'Spreads a poisonous, lachrymatory mist from its coral when attacked by intruders.'),
(3445, 'Coral Pressure', NULL, 'Releases high-pressure water from the ends of its arms.'),
(3446, 'Little Plasma', NULL, 'Fires weak energy shots from its palms.'),
(3447, 'Jack Raid', NULL, 'Turns invisible moments before charging and crashing into the enemy, striking them from behind while they are in a state of confusion.'),
(3448, 'Giant Grater', NULL, 'Grinds the enemy with the crystals on its arms.'),
(3449, 'Curse Reflection', NULL, 'Fires the light energy it has accumulated from the tips of its crystals.'),
(3450, 'Brunt Claw', NULL, 'The sharp claws on its forelimbs that it uses to fight back against intruders as they draw near.'),
(3451, 'Colony Torpedo', NULL, 'Small fish-shaped biological weapons fired from its back. Despite having a slow underwater speed, their nature is similar to that of mines in that they trigger a huge explosion on contact.'),
(3452, 'Barrage Sweeper', NULL, 'Shoots at long range, firing a barrage with the autocannon deployed from its left shoulder.'),
(3453, 'Resting Burner', NULL, 'A mid-range attack where it expels ultra-high temperature flames from the lion armor on its chest.'),
(3454, 'Sonic Excavator', NULL, 'A very-close range technique where it impales the enemy by launching its Pile Bunker while charging with its fighting spirit at its maximum.'),
(3455, 'Parabolic Junk', NULL, 'Hits the sack at the bottom of its cannon with its tail, and shoots junk parts out of it to drive away invading enemies.'),
(3456, 'Scrap Teeth', NULL, 'Bites into the enemy with its prided foreteeth.'),
(3457, 'Nitou Seirai', 'Dual Sword Stance Lightning', 'Cuts down the enemy with the lightning swords it holds by dual wielding them.'),
(3458, 'Shidou Ittetsu', 'Chivalry Tenacity', 'Erects a barrier of lightning and forces the enemy into a one-on-one battle.'),
(3459, 'Shinden Shouraikou', 'Divine Electricity-summoned Lightning', 'Condenses the electrical energy in its surroundings and fires an ultra-high density shot of lightning.'),
(3460, 'Eclipse None', NULL, 'Makes the energy that it shoots from both of its hands stick to the enemy, corroding them, and gnawing away at their whole body.'),
(3461, 'Bingerard', NULL, 'Transforms its right arm into a spear and pierces with it.'),
(3462, 'Death Charge', NULL, 'Transforms its left arm into a gun barrel and fires energy shots.'),
(3463, 'Anemodarmenos', 'Grc: Windswept', 'Confuses the enemy with afterimages caused by its high-speed movement.'),
(3464, 'Asteroeidis', 'Grc: Asteroid', 'A kicking technique that it dishes out using its swift speed.'),
(3465, 'Lónkhē Adistakto', 'Grc: Ruthless Spear', 'Throws its divine spear and ensures that it pierces the enemy''s Digicore.'),
(3466, 'Assault Hatchet', NULL, 'Strikes the enemy with an all-purpose hatchet that cuts down even large trees in an instant.'),
(3467, 'Tied-up Ivy', NULL, 'Restrains the enemy with the tentacles growing from the back of its head.'),
(3468, 'Shotgun Moss', NULL, 'Counterattacks enemies that attack from a distance by shooting poisonous grass needles that grow from its head like hair to restrict their movements.'),
(3469, 'Double Lariat', NULL, 'Mows down enemies in its surroundings by spinning both of its large arms.'),
(3470, 'Petit Tornado', NULL, 'A small tornado generated by the propeller rotation of both its ears.'),
(3471, 'Pyon Dump', 'Hop Dump', 'Jumps high into the sky and then crushes the enemy with its large build.'),
(3472, 'Sorblow', NULL, 'Punches the enemy with the flames it amasses in its hands.'),
(3473, 'Sorshot', NULL, 'Hurls the flames in its hands.'),
(3474, 'Bakōnya', 'Boxmeow', 'Hits the enemy with the corner of its delivery bag that it swings down.'),
(3475, 'Multiple Seed', NULL, 'Shoots countless seeds from the petals on its left shoulder like a machine gun.'),
(3476, 'Sprout Rush', NULL, 'Pierces the enemy with the flower spear it holds in its right hand.'),
(3477, 'Gran del Sol', 'Esp: Great of the Sun', 'Fires an extremely wide beam with the huge sword of light that appears from within its flower spear only when it has bloomed.'),
(3478, 'Mikkomi', 'Ear-strike', 'Slaps the opponent with its ears.'),
(3479, 'Gallia Fissure', NULL, 'Tears the enemy to pieces with its tough claws, boasts the power to easily cut through Chrome Digizoid, if it has a low purity.'),
(3480, 'Dragonia', NULL, 'Closes its wings and charges like a bullet of light.'),
(3481, 'Meteor Lux', 'Lat: "Meteor Light"', 'The light from its spread wings rains down as a meteor shower.'),
(3482, 'Gran Nova', NULL, 'Gathers all the energy in its body and fires the brightest fireball from its mouth, enveloping the enemy in a scorching-hot star.'),
(3483, 'Giton Isolation', 'False Escape Isolation', 'A mimicry technique where it blends itself into its surroundings, and uses it to creep up stealthily on the enemy.'),
(3484, 'Crack Haken', 'Crack Piton', 'A long-range attack in which it throws its pitons.'),
(3485, 'Dynamic Scyther', NULL, 'Spreads out its pickaxe arms and tears the enemy to pieces while spinning.'),
(3486, 'Fillet Blade', NULL, 'Slashes the enemy with the sharp fins all over its body.'),
(3487, 'Ripple Edge', NULL, 'Hurls pressurized water like a blade.'),
(3488, 'Liquid Veil', NULL, 'Envelops itself in water armor, enhancing its physical ability and allowing it exhibit the same strength in places without water as it does when it is underwater.'),
(3489, 'Innocence Blizzard', NULL, 'A ranged attack in which it generates a blizzard with its tail and wings.'),
(3490, 'Freezing Ray', NULL, 'Instantly turns the enemy into dry ice with a cold beam fired from its mouth.'),
(3491, 'Ruin Reverb', NULL, 'Sings with a beautiful cry that charms the listener, and causes those who finish listening to it to completely shatter internally.'),
(3492, 'Removal Blow', NULL, 'Unleashes a punch attack with its enormous right arm while charging.'),
(3493, 'Defrost Blade', NULL, 'Pierces the enemy using heat from the Heat Sword on its left arm.'),
(3494, 'Glaciate Missile', NULL, 'Shoots ice compacted from the snow that gets sucked in by its propeller, generating huge blocks of ice on impact that can be used to stop avalanches.'),
(3495, 'Senpū Baku', 'Whirlwind Bind', 'Restricts the opponent''s movements with a tornado unleashed from the Kikurin.'),
(3496, 'Kikurin Issen: Gouraizan', 'Chrysanthemum and Phosphorus Flash: Roaring Lightning Beheading', 'Charges at lightning speed and then bisects the enemy with the Kikurin as it surges with lightning.'),
(3497, 'Touka Seihitsu', 'Sword Brilliance Tranquility', 'Cuts down enemies in its surroundings with a single stroke of its sword.'),
(3498, 'Breaclaw', NULL, 'Accumulates energy in its left hand and unleashes a claw attack.'),
(3499, 'Kaisaisō', 'Calamity Claws', 'Slices open the enemy''s belly with its claws.'),
(3500, 'Kōhabattō', 'Knock Down', 'Repeatedly swings its two longswords with all its might to pulverize the enemy.')
ON CONFLICT (id) DO UPDATE SET nome = EXCLUDED.nome, traducao = EXCLUDED.traducao, descricao = EXCLUDED.descricao;

INSERT INTO habilidades (id, nome, traducao, descricao) VALUES
(3501, 'Fūga Rekkanjin', 'Wind Fang Intense Whirling Swiftness', 'Unleashes the vacuum blades wrapped around its longswords.'),
(3502, 'Gōon Kieizan', 'Great Grudge Destructive Eternal Beheading', 'Converts all of its reason into ferocity and bisects the enemy with its two longswords, slashing them while smashing them to smithereens at the same time.'),
(3503, 'Dream Hurricane', NULL, 'Jumps high into the sky and kicks while spinning.'),
(3504, 'Marble Impact', NULL, 'Puts all its strength into its fist and dishes out a seven-colored punch.'),
(3505, 'Lovely Shower', NULL, 'Punches its fist and fires heart-shaped energy shots at the enemy that have the effect of purifying their evil heart.'),
(3506, 'Sunakake', 'Sand Throw', 'Threatens enemies that approach with a large amount of sand.'),
(3507, 'Jive', NULL, 'Dishes out a barrage of quick kicks while standing on one leg.'),
(3508, 'Ländlizer', NULL, 'Spins its body and slashes the enemy with the razor-sharp tips of its ears.'),
(3509, 'Breakin'' Stream', NULL, 'Unleashes a powerful tornado from both of its hands.'),
(3510, 'Rhythmic Arts', NULL, 'Attacks the enemy with dance kenpō which incorporates capoeira and martial arts.'),
(3511, 'Howling Blast', NULL, 'Blows the enemy away with a very loud beat emitted from the speaker in its abdomen.'),
(3512, 'Upbeat Twister', NULL, 'Creates tornadoes and roaring sounds with its skillful footwork.'),
(3513, 'Physalist', NULL, 'Sends an electric shock stored in its palms through the enemy''s vitals.'),
(3514, 'Punischöne', 'Deu: "Punish Beauty"', 'Shocks and punishes the enemy in a stimulating manner with the high-voltage belts that extend from its body.'),
(3515, 'Vorsprite', NULL, 'Electrifies its body and rams into the enemy while spinning.'),
(3516, 'Birī Smasher', 'Shock Smasher', 'Sends its fists flying by accumulating electricity in its palms.'),
(3517, 'Hammer Thunder', NULL, 'Kicks the enemy up and then brings them down with both of its electrically-charged fists.'),
(3518, 'Adieu World', 'Fra: Goodbye World', 'Teleports by removing the space between it and the opponent.'),
(3519, 'Dokutease', NULL, 'Produces various medicines and injects them via its tentacles. It heals the wounds of its allies and temporarily boosts their power, but as for enemies, it disintegrates them from the inside out with a deadly poison, killing them.'),
(3520, 'Whirlpool Spin', NULL, 'Rotates its body like a spinning top and performs a ramming attack.'),
(3521, 'Liar Dream', NULL, 'Hijacks the consciousness of an opponent that meets its gaze.'),
(3522, 'Reaper Strike', NULL, 'Shoots at the opponent''s vitals with the CND-96 rifle on its right arm.'),
(3523, 'Desert Deathscythe', NULL, 'Tears the enemy to pieces with the scythe attached to the CND-96.'),
(3524, 'Wither Wing', NULL, 'Shoots out hordes of condors made of sand.'),
(3525, 'Sedna', NULL, 'Shoots high-powered shells from its two cannons.'),
(3526, 'Albion', NULL, NULL),
(3527, 'Bramble Shot', NULL, 'Shoots thorns from its handle.'),
(3528, 'Crimson Spores', NULL, 'Expels highly toxic spores from the protrusions on its back.'),
(3529, 'Killing Cadence', NULL, 'Mows down enemies in one go with its enlarged wheels.'),
